<script>
import { allTools, searchTools } from '@/data/tools'

export default {
  name: 'Layout',
  data() {
    return {
      searchKeyword: '',
      showSearchResults: false,
      isCollapse: false,
      backendAvailable: false,
      filteredTools: [],
      isMobile: false,
      // 标签页相关数据
      tabs: [
        { name: '首页', path: '/' }
      ],
      activeTab: '/'
    }
  },
  computed: {
    asideWidth() {
      if (this.isMobile) return this.isCollapse ? '0px' : '220px'
      return this.isCollapse ? '64px' : '220px'
    },
    allTools() {
      return allTools
    },
    pageTitle() {
      const tool = this.allTools.find(t => t.path === this.$route.path)
      return tool ? tool.name : 'IT Tools'
    },
    currentTheme() {
      return this.$store.state.theme
    },
    availableThemes() {
      return this.$store.state.themes
    }
  },
  methods: {
    toggleCollapse() {
      this.isCollapse = !this.isCollapse
    },
    goHome() {
      const currentPath = this.$route.path
      if (currentPath !== '/' && currentPath !== '') {
        this.$router.push('/')
      }
    },
    handleResize() {
      const mobile = window.innerWidth < 768
      if (mobile !== this.isMobile) {
        this.isMobile = mobile
        // 进入移动端时默认收起抽屉，回到桌面端时展开
        this.isCollapse = mobile
      }
    },
    handleSearch() {
      this.filteredTools = searchTools(this.searchKeyword, this.allTools, { limit: 15 })
    },
    goToTool(tool) {
      this.$router.push(tool.path)
      this.showSearchResults = false
      this.searchKeyword = ''
      if (this.isMobile) this.isCollapse = true
    },
    changeTheme(theme) {
      this.$store.dispatch('changeTheme', theme)
    },
    async checkBackend() {
      try {
        const controller = new AbortController()
        const timeoutId = setTimeout(() => controller.abort(), 3000)
        const response = await fetch('/api/ping', {
          method: 'GET',
          signal: controller.signal
        })
        clearTimeout(timeoutId)
        this.backendAvailable = response.ok
      } catch (e) {
        this.backendAvailable = false
      }
    },
    // 标签页相关方法
    handleTabClick(tab) {
      this.$router.push(tab.paneName)
    },
    handleTabRemove(path) {
      // 不能删除首页标签
      if (path === '/') return
      
      const index = this.tabs.findIndex(tab => tab.path === path)
      if (index > -1) {
        this.tabs.splice(index, 1)
        
        // 如果删除的是当前活跃标签，切换到前一个标签
        if (this.activeTab === path) {
          const newActiveTab = this.tabs[this.tabs.length - 1].path
          this.activeTab = newActiveTab
          this.$router.push(newActiveTab)
        }
      }
    },
    addTab() {
      const currentPath = this.$route.path
      const currentTool = this.allTools.find(t => t.path === currentPath)
      const tabName = currentTool ? currentTool.name : '页面'
      
      // 检查标签是否已存在
      const existingTab = this.tabs.find(tab => tab.path === currentPath)
      if (!existingTab) {
        this.tabs.push({ name: tabName, path: currentPath })
      }
      
      this.activeTab = currentPath
    }
  },
  watch: {
    // 监听路由变化，自动添加标签页
    '$route.path': {
      handler(newPath) {
        this.addTab()
        if (this.isMobile) this.isCollapse = true
      },
      immediate: true
    }
  },
  mounted() {
    this.checkBackend()
    this.handleResize()
    window.addEventListener('resize', this.handleResize)
    document.addEventListener('click', (e) => {
      if (!e.target.closest('.search-box')) {
        this.showSearchResults = false
      }
    })
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.handleResize)
  }
}
</script>

