<template>
  <div class="image-crop-tool">
    <el-card>
      <div slot="header">
        <span>图片裁剪工具</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="16">
          <div class="upload-area" v-if="!imageSrc">
            <el-upload
              drag
              action="#"
              :auto-upload="false"
              :show-file-list="false"
              accept="image/*"
              @change="handleImageUpload"
            >
              <i class="el-icon-upload"></i>
              <div class="el-upload__text">拖拽图片到此处，或<em>点击上传</em></div>
            </el-upload>
          </div>

          <div class="crop-container" v-else>
            <div class="image-wrapper" ref="imageWrapper">
              <img ref="image" :src="imageSrc" @load="onImageLoad" />
              <div 
                class="crop-box"
                :style="cropBoxStyle"
                @mousedown="startDrag"
              >
                <div class="resize-handle nw" @mousedown.stop="startResize('nw')"></div>
                <div class="resize-handle ne" @mousedown.stop="startResize('ne')"></div>
                <div class="resize-handle sw" @mousedown.stop="startResize('sw')"></div>
                <div class="resize-handle se" @mousedown.stop="startResize('se')"></div>
                <div class="crop-info">{{ cropWidth }} × {{ cropHeight }}</div>
              </div>
            </div>
          </div>
        </el-col>

        <el-col :span="8">
          <el-divider>裁剪设置</el-divider>
          
          <el-form label-width="80px">
            <el-form-item label="预设比例">
              <el-select v-model="aspectRatio" style="width: 100%" @change="applyAspectRatio">
                <el-option label="自由" :value="null" />
                <el-option label="1:1 (正方形)" value="1:1" />
                <el-option label="4:3" value="4:3" />
                <el-option label="16:9" value="16:9" />
                <el-option label="16:10" value="16:10" />
                <el-option label="2:3" value="2:3" />
                <el-option label="3:2" value="3:2" />
              </el-select>
            </el-form-item>

            <el-form-item label="X">
              <el-input-number v-model="crop.x" :min="0" :max="imageWidth" size="small" />
            </el-form-item>
            <el-form-item label="Y">
              <el-input-number v-model="crop.y" :min="0" :max="imageHeight" size="small" />
            </el-form-item>
            <el-form-item label="宽度">
              <el-input-number v-model="crop.width" :min="1" :max="imageWidth" size="small" />
            </el-form-item>
            <el-form-item label="高度">
              <el-input-number v-model="crop.height" :min="1" :max="imageHeight" size="small" />
            </el-form-item>
          </el-form>

          <el-divider>预览</el-divider>
          <div class="preview-container">
            <canvas ref="previewCanvas" class="preview-canvas"></canvas>
          </div>

          <el-divider>输出设置</el-divider>
          <el-form label-width="80px">
            <el-form-item label="格式">
              <el-select v-model="outputFormat" style="width: 100%">
                <el-option label="PNG" value="png" />
                <el-option label="JPEG" value="jpeg" />
                <el-option label="WebP" value="webp" />
              </el-select>
            </el-form-item>
            <el-form-item label="质量" v-if="outputFormat !== 'png'">
              <el-slider v-model="outputQuality" :min="0.1" :max="1" :step="0.1" />
            </el-form-item>
          </el-form>

          <div class="action-buttons">
            <el-button type="primary" @click="cropImage" :disabled="!imageSrc">裁剪</el-button>
            <el-button @click="resetCrop" :disabled="!imageSrc">重置</el-button>
            <el-button @click="clearImage">清除图片</el-button>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'ImageCropTool',
  data() {
    return {
      imageSrc: '',
      imageWidth: 0,
      imageHeight: 0,
      crop: {
        x: 0,
        y: 0,
        width: 100,
        height: 100
      },
      aspectRatio: null,
      outputFormat: 'png',
      outputQuality: 0.9,
      isDragging: false,
      isResizing: false,
      resizeHandle: null,
      startX: 0,
      startY: 0,
      startCrop: {}
    }
  },
  computed: {
    cropWidth() {
      return Math.round(this.crop.width)
    },
    cropHeight() {
      return Math.round(this.crop.height)
    },
    cropBoxStyle() {
      return {
        left: this.crop.x + 'px',
        top: this.crop.y + 'px',
        width: this.crop.width + 'px',
        height: this.crop.height + 'px'
      }
    }
  },
  methods: {
    handleImageUpload(file) {
      const reader = new FileReader()
      reader.onload = (e) => {
        this.imageSrc = e.target.result
      }
      reader.readAsDataURL(file.raw)
    },
    onImageLoad() {
      const img = this.$refs.image
      this.imageWidth = img.naturalWidth
      this.imageHeight = img.naturalHeight
      
      this.crop = {
        x: 0,
        y: 0,
        width: Math.min(200, this.imageWidth),
        height: Math.min(200, this.imageHeight)
      }
      
      this.updatePreview()
    },
    startDrag(e) {
      this.isDragging = true
      this.startX = e.clientX
      this.startY = e.clientY
      this.startCrop = { ...this.crop }
      
      document.addEventListener('mousemove', this.onDrag)
      document.addEventListener('mouseup', this.stopDrag)
    },
    onDrag(e) {
      if (!this.isDragging) return
      
      const dx = e.clientX - this.startX
      const dy = e.clientY - this.startY
      
      this.crop.x = Math.max(0, Math.min(this.imageWidth - this.crop.width, this.startCrop.x + dx))
      this.crop.y = Math.max(0, Math.min(this.imageHeight - this.crop.height, this.startCrop.y + dy))
      
      this.updatePreview()
    },
    stopDrag() {
      this.isDragging = false
      document.removeEventListener('mousemove', this.onDrag)
      document.removeEventListener('mouseup', this.stopDrag)
    },
    startResize(handle) {
      this.isResizing = true
      this.resizeHandle = handle
      this.startX = event.clientX
      this.startY = event.clientY
      this.startCrop = { ...this.crop }
      
      document.addEventListener('mousemove', this.onResize)
      document.addEventListener('mouseup', this.stopResize)
    },
    onResize(e) {
      if (!this.isResizing) return
      
      const dx = e.clientX - this.startX
      const dy = e.clientY - this.startY
      
      let newWidth = this.startCrop.width
      let newHeight = this.startCrop.height
      let newX = this.startCrop.x
      let newY = this.startCrop.y
      
      if (this.resizeHandle.includes('e')) {
        newWidth = Math.max(20, this.startCrop.width + dx)
      }
      if (this.resizeHandle.includes('w')) {
        newWidth = Math.max(20, this.startCrop.width - dx)
        newX = this.startCrop.x + this.startCrop.width - newWidth
      }
      if (this.resizeHandle.includes('s')) {
        newHeight = Math.max(20, this.startCrop.height + dy)
      }
      if (this.resizeHandle.includes('n')) {
        newHeight = Math.max(20, this.startCrop.height - dy)
        newY = this.startCrop.y + this.startCrop.height - newHeight
      }
      
      if (this.aspectRatio) {
        const [ratioW, ratioH] = this.aspectRatio.split(':').map(Number)
        const ratio = ratioW / ratioH
        
        if (this.resizeHandle.includes('e') || this.resizeHandle.includes('w')) {
          newHeight = newWidth / ratio
        } else {
          newWidth = newHeight * ratio
        }
      }
      
      this.crop.x = Math.max(0, newX)
      this.crop.y = Math.max(0, newY)
      this.crop.width = Math.min(newWidth, this.imageWidth - this.crop.x)
      this.crop.height = Math.min(newHeight, this.imageHeight - this.crop.y)
      
      this.updatePreview()
    },
    stopResize() {
      this.isResizing = false
      document.removeEventListener('mousemove', this.onResize)
      document.removeEventListener('mouseup', this.stopResize)
    },
    applyAspectRatio() {
      if (!this.aspectRatio) return
      
      const [ratioW, ratioH] = this.aspectRatio.split(':').map(Number)
      const ratio = ratioW / ratioH
      
      this.crop.height = this.crop.width / ratio
      this.updatePreview()
    },
    updatePreview() {
      const canvas = this.$refs.previewCanvas
      if (!canvas) return
      
      const ctx = canvas.getContext('2d')
      const img = this.$refs.image
      
      const maxSize = 200
      const scale = Math.min(maxSize / this.crop.width, maxSize / this.crop.height)
      
      canvas.width = this.crop.width * scale
      canvas.height = this.crop.height * scale
      
      ctx.drawImage(
        img,
        this.crop.x, this.crop.y, this.crop.width, this.crop.height,
        0, 0, canvas.width, canvas.height
      )
    },
    cropImage() {
      const canvas = document.createElement('canvas')
      canvas.width = this.crop.width
      canvas.height = this.crop.height
      
      const ctx = canvas.getContext('2d')
      const img = this.$refs.image
      
      ctx.drawImage(
        img,
        this.crop.x, this.crop.y, this.crop.width, this.crop.height,
        0, 0, this.crop.width, this.crop.height
      )
      
      const mimeType = `image/${this.outputFormat}`
      const quality = this.outputFormat === 'png' ? undefined : this.outputQuality
      
      canvas.toBlob((blob) => {
        const url = URL.createObjectURL(blob)
        const link = document.createElement('a')
        link.href = url
        link.download = `cropped-image.${this.outputFormat}`
        link.click()
        URL.revokeObjectURL(url)
        this.$message.success('裁剪完成')
      }, mimeType, quality)
    },
    resetCrop() {
      this.crop = {
        x: 0,
        y: 0,
        width: Math.min(200, this.imageWidth),
        height: Math.min(200, this.imageHeight)
      }
      this.aspectRatio = null
      this.updatePreview()
    },
    clearImage() {
      this.imageSrc = ''
      this.crop = { x: 0, y: 0, width: 100, height: 100 }
    }
  }
}
</script>

<style scoped>
.image-crop-tool {
  padding: 20px;
}

.upload-area {
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f5f7fa;
  border-radius: 8px;
}

.crop-container {
  position: relative;
  background: #f5f7fa;
  border-radius: 8px;
  overflow: auto;
  max-height: 500px;
}

.image-wrapper {
  position: relative;
  display: inline-block;
}

.image-wrapper img {
  display: block;
  max-width: 100%;
}

.crop-box {
  position: absolute;
  border: 2px dashed #409eff;
  background: rgba(64, 158, 255, 0.1);
  cursor: move;
}

.resize-handle {
  position: absolute;
  width: 10px;
  height: 10px;
  background: #409eff;
  border: 2px solid white;
  border-radius: 50%;
}

.resize-handle.nw { top: -5px; left: -5px; cursor: nw-resize; }
.resize-handle.ne { top: -5px; right: -5px; cursor: ne-resize; }
.resize-handle.sw { bottom: -5px; left: -5px; cursor: sw-resize; }
.resize-handle.se { bottom: -5px; right: -5px; cursor: se-resize; }

.crop-info {
  position: absolute;
  bottom: 5px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(0, 0, 0, 0.7);
  color: white;
  padding: 2px 8px;
  border-radius: 3px;
  font-size: 12px;
  white-space: nowrap;
}

.preview-container {
  display: flex;
  justify-content: center;
  background: #f5f7fa;
  border-radius: 8px;
  padding: 10px;
  min-height: 100px;
}

.preview-canvas {
  border: 1px solid #dcdfe6;
  border-radius: 4px;
}

.action-buttons {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
</style>
