<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>大小写转换</span>
        <el-button size="small" @click="clearAll">清空</el-button>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="11">
          <div class="input-section">
            <div class="section-header">
              <span>输入文本</span>
              <el-tag size="mini" type="primary">输入或输出</el-tag>
            </div>
            <el-input
              v-model="inputText"
              type="textarea"
              :rows="8"
              placeholder="请输入要转换的文本"
            />
          </div>
        </el-col>
        
        <el-col :span="2" class="actions-col">
          <div class="action-buttons">
            <el-button type="primary" circle @click="convertForward" title="转换">
              <i class="el-icon-right"></i>
            </el-button>
            <span class="action-label">转换</span>
            <el-button type="success" circle @click="convertBackward" title="反向转换">
              <i class="el-icon-back"></i>
            </el-button>
            <span class="action-label">反向</span>
          </div>
        </el-col>
        
        <el-col :span="11">
          <div class="output-section">
            <div class="section-header">
              <span>转换结果</span>
              <el-tag size="mini" type="success">输入或输出</el-tag>
            </div>
            <el-input
              v-model="outputText"
              type="textarea"
              :rows="8"
              placeholder="转换结果将显示在这里"
            />
          </div>
        </el-col>
      </el-row>

      <el-row :gutter="10" style="margin-top: 20px">
        <el-col :span="24" class="conversion-options">
          <span class="options-label">转换方式：</span>
          <el-radio-group v-model="conversionType" size="small">
            <el-radio-button label="upper">转大写</el-radio-button>
            <el-radio-button label="lower">转小写</el-radio-button>
            <el-radio-button label="camel">驼峰式</el-radio-button>
            <el-radio-button label="pascal">帕斯卡</el-radio-button>
            <el-radio-button label="snake">蛇形式</el-radio-button>
            <el-radio-button label="kebab">短横线</el-radio-button>
            <el-radio-button label="constant">常量式</el-radio-button>
          </el-radio-group>
        </el-col>
      </el-row>

      <el-divider>批量转换预览</el-divider>

      <el-row v-if="inputText">
        <el-col :span="24">
          <el-table :data="previewData" border size="small">
            <el-table-column prop="name" label="转换类型" width="150" />
            <el-table-column prop="value" label="结果">
              <template slot-scope="scope">
                <code>{{ scope.row.value }}</code>
                <el-button
                  type="text"
                  size="mini"
                  style="float: right"
                  @click="applyConversion(scope.row.type)"
                >应用</el-button>
              </template>
            </el-table-column>
          </el-table>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CaseTool',
  data() {
    return {
      inputText: '',
      outputText: '',
      conversionType: 'upper'
    }
  },
  computed: {
    previewData() {
      if (!this.inputText) return []
      return [
        { name: '大写', value: this.inputText.toUpperCase(), type: 'upper' },
        { name: '小写', value: this.inputText.toLowerCase(), type: 'lower' },
        { name: '驼峰式', value: this.convertToCamelCase(this.inputText), type: 'camel' },
        { name: '帕斯卡式', value: this.convertToPascalCase(this.inputText), type: 'pascal' },
        { name: '蛇形式', value: this.convertToSnakeCase(this.inputText), type: 'snake' },
        { name: '短横线式', value: this.convertToKebabCase(this.inputText), type: 'kebab' },
        { name: '常量式', value: this.convertToConstantCase(this.inputText), type: 'constant' }
      ]
    }
  },
  methods: {
    convertForward() {
      if (!this.inputText) {
        this.$message.warning('请输入要转换的文本')
        return
      }
      this.outputText = this.convert(this.inputText, this.conversionType)
      this.$message.success('转换成功')
    },
    convertBackward() {
      if (!this.outputText) {
        this.$message.warning('请输入要转换的文本')
        return
      }
      this.inputText = this.convert(this.outputText, this.conversionType)
      this.$message.success('转换成功')
    },
    convert(text, type) {
      switch (type) {
        case 'upper': return text.toUpperCase()
        case 'lower': return text.toLowerCase()
        case 'camel': return this.convertToCamelCase(text)
        case 'pascal': return this.convertToPascalCase(text)
        case 'snake': return this.convertToSnakeCase(text)
        case 'kebab': return this.convertToKebabCase(text)
        case 'constant': return this.convertToConstantCase(text)
        default: return text
      }
    },
    applyConversion(type) {
      this.conversionType = type
      this.outputText = this.convert(this.inputText, type)
      this.$message.success('已应用转换')
    },
    convertToCamelCase(str) {
      return str
        .replace(/[-_\s]+(.)?/g, (_, char) => char ? char.toUpperCase() : '')
        .replace(/^[A-Z]/, char => char.toLowerCase())
    },
    convertToPascalCase(str) {
      return str
        .replace(/[-_\s]+(.)?/g, (_, char) => char ? char.toUpperCase() : '')
        .replace(/^[a-z]/, char => char.toUpperCase())
    },
    convertToSnakeCase(str) {
      return str
        .replace(/([A-Z])/g, '_$1')
        .replace(/[-\s]+/g, '_')
        .toLowerCase()
        .replace(/^_/, '')
    },
    convertToKebabCase(str) {
      return str
        .replace(/([A-Z])/g, '-$1')
        .replace(/[_\s]+/g, '-')
        .toLowerCase()
        .replace(/^-/, '')
    },
    convertToConstantCase(str) {
      return this.convertToSnakeCase(str).toUpperCase()
    },
    clearAll() {
      this.inputText = ''
      this.outputText = ''
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .input-section, .output-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }

  .actions-col {
    display: flex;
    align-items: center;
    justify-content: center;

    .action-buttons {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 10px;

      .action-label {
        font-size: 12px;
        color: #606266;
        margin-bottom: 10px;
      }
    }
  }

  .conversion-options {
    display: flex;
    align-items: center;
    gap: 10px;

    .options-label {
      font-weight: bold;
      white-space: nowrap;
    }
  }

  code {
    background: #f5f7fa;
    padding: 2px 6px;
    border-radius: 3px;
    font-family: monospace;
  }
}
</style>
