<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>密码生成器</span>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="12">
          <el-form label-width="140px">
            <el-form-item label="密码长度">
              <el-slider v-model="length" :min="4" :max="64" show-input />
            </el-form-item>
            
            <el-form-item label="生成数量">
              <el-input-number v-model="count" :min="1" :max="20" />
            </el-form-item>
            
            <el-form-item label="包含字符">
              <el-checkbox v-model="includeUppercase">大写字母 (A-Z)</el-checkbox>
              <el-checkbox v-model="includeLowercase">小写字母 (a-z)</el-checkbox>
              <el-checkbox v-model="includeNumbers">数字 (0-9)</el-checkbox>
              <el-checkbox v-model="includeSymbols">特殊符号 (!@#$...)</el-checkbox>
            </el-form-item>
            
            <el-form-item label="排除相似字符">
              <el-checkbox v-model="excludeSimilar">排除 0, O, l, 1 等</el-checkbox>
            </el-form-item>
            
            <el-form-item>
              <el-button type="primary" @click="generate">生成密码</el-button>
              <el-button @click="clear">清空</el-button>
            </el-form-item>
          </el-form>
        </el-col>
        
        <el-col :span="12">
          <div class="result-section">
            <div class="section-header">
              <span>生成结果</span>
              <el-button type="text" size="mini" @click="copyAll">复制全部</el-button>
            </div>
            <el-input
              v-model="result"
              type="textarea"
              :rows="12"
              readonly
              placeholder="生成的密码将显示在这里"
            />
          </div>
        </el-col>
      </el-row>

      <el-row v-if="passwords.length > 0" style="margin-top: 20px">
        <el-col :span="24">
          <el-table :data="passwords" border size="small">
            <el-table-column type="index" width="60" align="center" />
            <el-table-column prop="password" label="密码">
              <template slot-scope="scope">
                <code class="password-text">{{ scope.row.password }}</code>
                <el-tag :type="getStrengthType(scope.row.strength)" size="mini" style="margin-left: 10px">
                  {{ scope.row.strength }}
                </el-tag>
              </template>
            </el-table-column>
            <el-table-column width="100" align="center">
              <template slot-scope="scope">
                <el-button type="text" size="mini" @click="copy(scope.row.password)">复制</el-button>
              </template>
            </el-table-column>
          </el-table>
        </el-col>
      </el-row>

      <el-divider>密码强度检测</el-divider>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-input
            v-model="testPassword"
            placeholder="输入要检测的密码..."
            show-password
            @input="onTestPasswordChange"
          >
            <template slot="append">
              <el-button icon="el-icon-view" @click="testPasswordVisible = !testPasswordVisible"></el-button>
            </template>
          </el-input>
        </el-col>
        <el-col :span="12">
          <div v-if="testPassword" class="strength-display">
            <el-progress
              :percentage="testStrengthPercent"
              :color="testStrengthColor"
              :show-text="false"
              style="width: 200px; display: inline-block; vertical-align: middle;"
            />
            <el-tag :type="getStrengthType(testStrength)" size="small" style="margin-left: 10px">
              {{ testStrength }}
            </el-tag>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'PasswordTool',
  data() {
    return {
      length: 16,
      count: 5,
      includeUppercase: true,
      includeLowercase: true,
      includeNumbers: true,
      includeSymbols: true,
      excludeSimilar: false,
      result: '',
      passwords: [],
      testPassword: '',
      testPasswordVisible: false,
      testStrength: '',
      testStrengthPercent: 0,
      testStrengthColor: '#909399'
    }
  },
  computed: {},
  methods: {
    generate() {
      if (!this.includeUppercase && !this.includeLowercase && 
          !this.includeNumbers && !this.includeSymbols) {
        this.$message.warning('请至少选择一种字符类型')
        return
      }
      
      this.passwords = []
      const results = []
      
      for (let i = 0; i < this.count; i++) {
        const password = this.generatePassword()
        const strength = this.checkStrength(password)
        this.passwords.push({ password, strength })
        results.push(password)
      }
      
      this.result = results.join('\n')
    },
    generatePassword() {
      let chars = ''
      
      if (this.includeUppercase) chars += 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
      if (this.includeLowercase) chars += 'abcdefghijklmnopqrstuvwxyz'
      if (this.includeNumbers) chars += '0123456789'
      if (this.includeSymbols) chars += '!@#$%^&*()_+-=[]{}|;:,.<>?'
      
      if (this.excludeSimilar) {
        chars = chars.replace(/[0O1lI]/g, '')
      }
      
      let password = ''
      const array = new Uint32Array(this.length)
      window.crypto.getRandomValues(array)
      
      for (let i = 0; i < this.length; i++) {
        password += chars[array[i] % chars.length]
      }
      
      return password
    },
    checkStrength(password) {
      let score = 0
      
      if (password.length >= 8) score++
      if (password.length >= 12) score++
      if (/[a-z]/.test(password)) score++
      if (/[A-Z]/.test(password)) score++
      if (/[0-9]/.test(password)) score++
      if (/[^a-zA-Z0-9]/.test(password)) score++
      
      if (score <= 2) return '弱'
      if (score <= 4) return '中'
      return '强'
    },
    getStrengthType(strength) {
      switch (strength) {
        case '弱': return 'danger'
        case '中': return 'warning'
        case '强': return 'success'
        default: return ''
      }
    },
    clear() {
      this.result = ''
      this.passwords = []
    },
    copy(text) {
      navigator.clipboard.writeText(text).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    copyAll() {
      if (!this.result) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.result).then(() => {
        this.$message.success('已复制全部到剪贴板')
      })
    },
    onTestPasswordChange() {
      if (!this.testPassword) {
        this.testStrength = ''
        this.testStrengthPercent = 0
        this.testStrengthColor = '#909399'
        return
      }
      this.testStrength = this.checkStrength(this.testPassword)
      const scoreMap = { '弱': 33, '中': 66, '强': 100 }
      const colorMap = { '弱': '#F56C6C', '中': '#E6A23C', '强': '#67C23A' }
      this.testStrengthPercent = scoreMap[this.testStrength] || 0
      this.testStrengthColor = colorMap[this.testStrength] || '#909399'
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .result-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }

  .password-text {
    font-family: monospace;
    font-size: 14px;
    letter-spacing: 1px;
  }
}
</style>
