<template>
  <div class="excel-preview-tool">
    <el-card>
      <div slot="header">
        <span>Excel 预览工具</span>
        <el-tag v-if="!backendAvailable" type="warning" style="margin-left: 10px">需要后端服务</el-tag>
      </div>

      <el-row :gutter="20">
        <el-col :span="24">
          <div class="upload-area" @click="triggerUpload" @drop.prevent="handleDrop" @dragover.prevent>
            <input type="file" ref="fileInput" @change="handleFileSelect" accept=".xlsx,.xls,.csv" style="display: none" />
            <div v-if="!excelFile" class="upload-placeholder">
              <i class="el-icon-document" style="font-size: 48px; color: #909399"></i>
              <p>点击或拖拽Excel文件到此处</p>
              <p style="color: #909399; font-size: 12px">支持 .xlsx, .xls, .csv 格式</p>
            </div>
            <div v-else class="file-info">
              <i class="el-icon-document" style="font-size: 48px; color: #67C23A"></i>
              <p>{{ excelFile.name }}</p>
              <p style="color: #909399; font-size: 12px">{{ formatFileSize(excelFile.size) }}</p>
            </div>
          </div>
        </el-col>
      </el-row>

      <el-divider v-if="excelData.length > 0">工作表选择</el-divider>

      <el-form v-if="sheetNames.length > 1" label-width="100px">
        <el-form-item label="工作表">
          <el-radio-group v-model="activeSheet" @change="loadSheet">
            <el-radio-button v-for="name in sheetNames" :key="name" :label="name">{{ name }}</el-radio-button>
          </el-radio-group>
        </el-form-item>
      </el-form>

      <el-divider v-if="excelData.length > 0">数据预览</el-divider>

      <div v-if="excelData.length > 0" class="table-container">
        <el-table :data="excelData" border stripe max-height="500" style="width: 100%">
          <el-table-column
            v-for="(col, index) in columns"
            :key="index"
            :prop="col.prop"
            :label="col.label"
            min-width="120"
            show-overflow-tooltip
          />
        </el-table>
        <div class="table-info">
          <el-tag>共 {{ excelData.length }} 行数据</el-tag>
          <el-tag style="margin-left: 10px">{{ columns.length }} 列</el-tag>
        </div>
      </div>

      <el-divider v-if="excelData.length > 0">操作</el-divider>

      <el-form v-if="excelData.length > 0" label-width="100px">
        <el-form-item>
          <el-button type="primary" @click="exportJson">导出 JSON</el-button>
          <el-button type="success" @click="exportCsv">导出 CSV</el-button>
          <el-button @click="copyTable">复制表格</el-button>
          <el-button @click="clearAll">清空</el-button>
        </el-form-item>
      </el-form>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'ExcelPreviewTool',
  data() {
    return {
      backendAvailable: false,
      excelFile: null,
      workbook: null,
      sheetNames: [],
      activeSheet: '',
      excelData: [],
      columns: []
    }
  },
  async mounted() {
    await this.checkBackend()
    this.loadXlsxJs()
  },
  methods: {
    async checkBackend() {
      try {
        const response = await fetch('/api/ping', { 
          method: 'GET',
          signal: AbortSignal.timeout(3000)
        })
        this.backendAvailable = response.ok
      } catch (e) {
        this.backendAvailable = false
      }
    },
    loadXlsxJs() {
      if (window.XLSX) return
      
      const script = document.createElement('script')
      script.src = 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js'
      document.head.appendChild(script)
    },
    triggerUpload() {
      this.$refs.fileInput.click()
    },
    handleFileSelect(e) {
      const file = e.target.files[0]
      if (file) {
        this.loadExcel(file)
      }
    },
    handleDrop(e) {
      const file = e.dataTransfer.files[0]
      if (file && (file.name.endsWith('.xlsx') || file.name.endsWith('.xls') || file.name.endsWith('.csv'))) {
        this.loadExcel(file)
      }
    },
    async loadExcel(file) {
      this.excelFile = file
      
      if (!window.XLSX) {
        this.$message.warning('SheetJS 正在加载，请稍后重试')
        setTimeout(() => this.loadExcel(file), 1000)
        return
      }

      try {
        const arrayBuffer = await file.arrayBuffer()
        this.workbook = window.XLSX.read(arrayBuffer, { type: 'array' })
        this.sheetNames = this.workbook.SheetNames
        this.activeSheet = this.sheetNames[0]
        this.loadSheet()
      } catch (error) {
        this.$message.error('Excel 加载失败: ' + error.message)
      }
    },
    loadSheet() {
      if (!this.workbook || !this.activeSheet) return

      const sheet = this.workbook.Sheets[this.activeSheet]
      const jsonData = window.XLSX.utils.sheet_to_json(sheet, { header: 1 })

      if (jsonData.length === 0) {
        this.excelData = []
        this.columns = []
        return
      }

      const headers = jsonData[0]
      this.columns = headers.map((header, index) => ({
        prop: `col_${index}`,
        label: header || `列${index + 1}`
      }))

      this.excelData = jsonData.slice(1).map((row, rowIndex) => {
        const obj = {}
        headers.forEach((_, colIndex) => {
          obj[`col_${colIndex}`] = row[colIndex] !== undefined ? row[colIndex] : ''
        })
        return obj
      })
    },
    exportJson() {
      const sheet = this.workbook.Sheets[this.activeSheet]
      const jsonData = window.XLSX.utils.sheet_to_json(sheet)
      
      const blob = new Blob([JSON.stringify(jsonData, null, 2)], { type: 'application/json' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `${this.excelFile.name.replace(/\.[^/.]+$/, '')}.json`
      link.click()
      URL.revokeObjectURL(url)
    },
    exportCsv() {
      const sheet = this.workbook.Sheets[this.activeSheet]
      const csv = window.XLSX.utils.sheet_to_csv(sheet)
      
      const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `${this.excelFile.name.replace(/\.[^/.]+$/, '')}.csv`
      link.click()
      URL.revokeObjectURL(url)
    },
    copyTable() {
      const sheet = this.workbook.Sheets[this.activeSheet]
      const csv = window.XLSX.utils.sheet_to_csv(sheet)
      
      navigator.clipboard.writeText(csv).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    formatFileSize(bytes) {
      if (bytes < 1024) return bytes + ' B'
      if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(2) + ' KB'
      return (bytes / (1024 * 1024)).toFixed(2) + ' MB'
    },
    clearAll() {
      this.excelFile = null
      this.workbook = null
      this.sheetNames = []
      this.activeSheet = ''
      this.excelData = []
      this.columns = []
      this.$refs.fileInput.value = ''
    }
  }
}
</script>

<style scoped>
.excel-preview-tool {
  padding: 20px;
}

.upload-area {
  border: 2px dashed #dcdfe6;
  border-radius: 8px;
  min-height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: border-color 0.3s;
}

.upload-area:hover {
  border-color: #67C23A;
}

.upload-placeholder,
.file-info {
  text-align: center;
  color: #909399;
}

.table-container {
  margin-top: 20px;
}

.table-info {
  margin-top: 10px;
  text-align: center;
}
</style>
