<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>加密工具</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>
      
      <el-tabs v-model="activeTab">
        <el-tab-pane label="RSA 密钥对" name="rsa">
          <div class="tab-content">
            <el-row :gutter="20">
              <el-col :span="12">
                <div class="section-header">
                  <span>密钥生成</span>
                </div>
                <el-form :model="rsaForm" label-width="100px" size="small">
                  <el-form-item label="密钥长度">
                    <el-select v-model="rsaForm.keySize">
                      <el-option label="1024 位" :value="1024" />
                      <el-option label="2048 位" :value="2048" />
                      <el-option label="4096 位" :value="4096" />
                    </el-select>
                  </el-form-item>
                  <el-form-item>
                    <el-button type="primary" @click="generateRsaKeyPair" :loading="rsaForm.loading">
                      生成密钥对
                    </el-button>
                  </el-form-item>
                </el-form>
              </el-col>
              
              <el-col :span="12">
                <div class="section-header">
                  <span>密钥信息</span>
                </div>
                <el-descriptions :column="1" border size="small">
                  <el-descriptions-item label="公钥格式">PEM</el-descriptions-item>
                  <el-descriptions-item label="私钥格式">PKCS#8</el-descriptions-item>
                  <el-descriptions-item label="算法">RSA</el-descriptions-item>
                  <el-descriptions-item label="状态">
                    <el-tag v-if="rsaForm.hasKeys" type="success">已生成</el-tag>
                    <el-tag v-else type="info">未生成</el-tag>
                  </el-descriptions-item>
                </el-descriptions>
              </el-col>
            </el-row>
            
            <el-divider>密钥内容</el-divider>
            
            <el-row :gutter="20">
              <el-col :span="12">
                <div class="section-header">
                  <span>公钥</span>
                  <div>
                    <el-button type="text" size="mini" @click="copyPublicKey">复制</el-button>
                    <el-button type="text" size="mini" @click="downloadPublicKey">下载</el-button>
                  </div>
                </div>
                <el-input
                  v-model="rsaForm.publicKey"
                  type="textarea"
                  :rows="10"
                  readonly
                  placeholder="生成的公钥将显示在这里..."
                />
              </el-col>
              
              <el-col :span="12">
                <div class="section-header">
                  <span>私钥</span>
                  <div>
                    <el-button type="text" size="mini" @click="copyPrivateKey">复制</el-button>
                    <el-button type="text" size="mini" @click="downloadPrivateKey">下载</el-button>
                  </div>
                </div>
                <el-input
                  v-model="rsaForm.privateKey"
                  type="textarea"
                  :rows="10"
                  readonly
                  placeholder="生成的私钥将显示在这里..."
                />
              </el-col>
            </el-row>
          </div>
        </el-tab-pane>
        
        <el-tab-pane label="RSA 加密/解密" name="rsa-crypto">
          <div class="tab-content">
            <el-row :gutter="20">
              <el-col :span="12">
                <div class="section-header">
                  <span>加密</span>
                </div>
                <el-input
                  v-model="rsaCrypto.encryptText"
                  type="textarea"
                  :rows="5"
                  placeholder="输入要加密的文本"
                />
                <el-input
                  v-model="rsaCrypto.publicKey"
                  type="textarea"
                  :rows="5"
                  placeholder="输入公钥"
                  style="margin-top: 10px"
                />
                <el-button type="primary" style="margin-top: 10px" @click="rsaEncrypt">
                  加密
                </el-button>
              </el-col>
              
              <el-col :span="12">
                <div class="section-header">
                  <span>解密</span>
                </div>
                <el-input
                  v-model="rsaCrypto.decryptText"
                  type="textarea"
                  :rows="5"
                  placeholder="输入要解密的文本（Base64）"
                />
                <el-input
                  v-model="rsaCrypto.privateKey"
                  type="textarea"
                  :rows="5"
                  placeholder="输入私钥"
                  style="margin-top: 10px"
                />
                <el-button type="primary" style="margin-top: 10px" @click="rsaDecrypt">
                  解密
                </el-button>
              </el-col>
            </el-row>
            
            <el-divider>结果</el-divider>
            
            <el-input
              v-model="rsaCrypto.result"
              type="textarea"
              :rows="8"
              readonly
              placeholder="加密/解密结果将显示在这里..."
            />
          </div>
        </el-tab-pane>
        
        <el-tab-pane label="AES 加密/解密" name="aes">
          <div class="tab-content">
            <el-row :gutter="20">
              <el-col :span="12">
                <div class="section-header">
                  <span>加密</span>
                </div>
                <el-input
                  v-model="aesCrypto.encryptText"
                  type="textarea"
                  :rows="5"
                  placeholder="输入要加密的文本"
                />
                <el-form :model="aesCrypto" label-width="80px" size="small" style="margin-top: 10px">
                  <el-form-item label="密钥">
                    <el-input v-model="aesCrypto.key" placeholder="输入密钥" />
                  </el-form-item>
                  <el-form-item label="IV">
                    <el-input v-model="aesCrypto.iv" placeholder="输入初始化向量（可选）" />
                  </el-form-item>
                  <el-form-item label="模式">
                    <el-select v-model="aesCrypto.mode">
                      <el-option label="CBC" value="AES-CBC" />
                      <el-option label="GCM" value="AES-GCM" />
                    </el-select>
                  </el-form-item>
                </el-form>
                <el-button type="primary" @click="aesEncrypt">
                  加密
                </el-button>
              </el-col>
              
              <el-col :span="12">
                <div class="section-header">
                  <span>解密</span>
                </div>
                <el-input
                  v-model="aesCrypto.decryptText"
                  type="textarea"
                  :rows="5"
                  placeholder="输入要解密的文本（Base64）"
                />
                <el-form :model="aesCrypto" label-width="80px" size="small" style="margin-top: 10px">
                  <el-form-item label="密钥">
                    <el-input v-model="aesCrypto.key" placeholder="输入密钥" />
                  </el-form-item>
                  <el-form-item label="IV">
                    <el-input v-model="aesCrypto.iv" placeholder="输入初始化向量（可选）" />
                  </el-form-item>
                  <el-form-item label="模式">
                    <el-select v-model="aesCrypto.mode">
                      <el-option label="CBC" value="AES-CBC" />
                      <el-option label="GCM" value="AES-GCM" />
                    </el-select>
                  </el-form-item>
                </el-form>
                <el-button type="primary" @click="aesDecrypt">
                  解密
                </el-button>
              </el-col>
            </el-row>
            
            <el-divider>结果</el-divider>
            
            <el-input
              v-model="aesCrypto.result"
              type="textarea"
              :rows="8"
              readonly
              placeholder="加密/解密结果将显示在这里..."
            />
          </div>
        </el-tab-pane>
        
        <el-tab-pane label="MD5/SHA 哈希" name="hash">
          <div class="tab-content">
            <el-input
              v-model="hashText"
              type="textarea"
              :rows="5"
              placeholder="输入要计算哈希的文本"
            />
            <el-button type="primary" style="margin-top: 10px" @click="calculateHash">
              计算哈希
            </el-button>
            
            <el-divider>哈希结果</el-divider>
            
            <el-row :gutter="20">
              <el-col :span="8">
                <div class="section-header">
                  <span>MD5</span>
                  <el-button type="text" size="mini" @click="copyHash('md5')">复制</el-button>
                </div>
                <el-input
                  v-model="hashResults.md5"
                  readonly
                  placeholder="MD5 哈希值"
                />
              </el-col>
              
              <el-col :span="8">
                <div class="section-header">
                  <span>SHA-1</span>
                  <el-button type="text" size="mini" @click="copyHash('sha1')">复制</el-button>
                </div>
                <el-input
                  v-model="hashResults.sha1"
                  readonly
                  placeholder="SHA-1 哈希值"
                />
              </el-col>
              
              <el-col :span="8">
                <div class="section-header">
                  <span>SHA-256</span>
                  <el-button type="text" size="mini" @click="copyHash('sha256')">复制</el-button>
                </div>
                <el-input
                  v-model="hashResults.sha256"
                  readonly
                  placeholder="SHA-256 哈希值"
                />
              </el-col>
            </el-row>
            
            <el-row :gutter="20" style="margin-top: 10px">
              <el-col :span="8">
                <div class="section-header">
                  <span>SHA-384</span>
                  <el-button type="text" size="mini" @click="copyHash('sha384')">复制</el-button>
                </div>
                <el-input
                  v-model="hashResults.sha384"
                  readonly
                  placeholder="SHA-384 哈希值"
                />
              </el-col>
              
              <el-col :span="8">
                <div class="section-header">
                  <span>SHA-512</span>
                  <el-button type="text" size="mini" @click="copyHash('sha512')">复制</el-button>
                </div>
                <el-input
                  v-model="hashResults.sha512"
                  readonly
                  placeholder="SHA-512 哈希值"
                />
              </el-col>
            </el-row>
          </div>
        </el-tab-pane>
        
        <el-tab-pane label="HMAC" name="hmac">
          <div class="tab-content">
            <el-form :model="hmacForm" label-width="80px" size="small">
              <el-form-item label="文本">
                <el-input v-model="hmacForm.text" type="textarea" :rows="3" placeholder="输入文本" />
              </el-form-item>
              <el-form-item label="密钥">
                <el-input v-model="hmacForm.key" placeholder="输入密钥" />
              </el-form-item>
              <el-form-item label="算法">
                <el-select v-model="hmacForm.algorithm">
                  <el-option label="SHA-256" value="SHA-256" />
                  <el-option label="SHA-384" value="SHA-384" />
                  <el-option label="SHA-512" value="SHA-512" />
                </el-select>
              </el-form-item>
              <el-form-item>
                <el-button type="primary" @click="calculateHmac">计算 HMAC</el-button>
              </el-form-item>
            </el-form>
            
            <el-divider>HMAC 结果</el-divider>
            
            <div class="section-header">
              <span>HMAC 值</span>
              <el-button type="text" size="mini" @click="copyHmac">复制</el-button>
            </div>
            <el-input
              v-model="hmacForm.result"
              type="textarea"
              :rows="5"
              readonly
              placeholder="HMAC 值将显示在这里..."
            />
          </div>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CryptoTool',
  data() {
    return {
      activeTab: 'rsa',
      rsaForm: {
        keySize: 2048,
        loading: false,
        hasKeys: false,
        publicKey: '',
        privateKey: ''
      },
      rsaCrypto: {
        encryptText: '',
        publicKey: '',
        decryptText: '',
        privateKey: '',
        result: ''
      },
      aesCrypto: {
        encryptText: '',
        decryptText: '',
        key: '',
        iv: '',
        mode: 'AES-CBC',
        result: ''
      },
      hashText: '',
      hashResults: {
        md5: '',
        sha1: '',
        sha256: '',
        sha384: '',
        sha512: ''
      },
      hmacForm: {
        text: '',
        key: '',
        algorithm: 'SHA-256',
        result: ''
      }
    }
  },
  methods: {
    async generateRsaKeyPair() {
      this.rsaForm.loading = true
      
      try {
        const keyPair = await window.crypto.subtle.generateKey(
          {
            name: 'RSASSA-PKCS1-v1_5',
            modulusLength: this.rsaForm.keySize,
            publicExponent: new Uint8Array([1, 0, 1]),
            hash: 'SHA-256'
          },
          true,
          ['sign', 'verify']
        )
        
        const publicKeyBuffer = await window.crypto.subtle.exportKey('spki', keyPair.publicKey)
        const privateKeyBuffer = await window.crypto.subtle.exportKey('pkcs8', keyPair.privateKey)
        
        this.rsaForm.publicKey = this.arrayBufferToPem(publicKeyBuffer, 'PUBLIC KEY')
        this.rsaForm.privateKey = this.arrayBufferToPem(privateKeyBuffer, 'PRIVATE KEY')
        this.rsaForm.hasKeys = true
        
        this.$message.success('密钥对生成成功')
      } catch (error) {
        this.$message.error('密钥对生成失败: ' + error.message)
      } finally {
        this.rsaForm.loading = false
      }
    },
    async rsaEncrypt() {
      if (!this.rsaCrypto.encryptText || !this.rsaCrypto.publicKey) {
        this.$message.warning('请输入加密文本和公钥')
        return
      }
      
      try {
        const publicKey = await this.importPublicKey(this.rsaCrypto.publicKey)
        const encoder = new TextEncoder()
        const data = encoder.encode(this.rsaCrypto.encryptText)
        const encrypted = await window.crypto.subtle.encrypt(
          {
            name: 'RSA-OAEP'
          },
          publicKey,
          data
        )
        
        this.rsaCrypto.result = this.arrayBufferToBase64(encrypted)
        this.$message.success('加密成功')
      } catch (error) {
        this.$message.error('加密失败: ' + error.message)
      }
    },
    async rsaDecrypt() {
      if (!this.rsaCrypto.decryptText || !this.rsaCrypto.privateKey) {
        this.$message.warning('请输入解密文本和私钥')
        return
      }
      
      try {
        const privateKey = await this.importPrivateKey(this.rsaCrypto.privateKey)
        const encryptedData = this.base64ToArrayBuffer(this.rsaCrypto.decryptText)
        const decrypted = await window.crypto.subtle.decrypt(
          {
            name: 'RSA-OAEP'
          },
          privateKey,
          encryptedData
        )
        
        const decoder = new TextDecoder()
        this.rsaCrypto.result = decoder.decode(decrypted)
        this.$message.success('解密成功')
      } catch (error) {
        this.$message.error('解密失败: ' + error.message)
      }
    },
    async aesEncrypt() {
      if (!this.aesCrypto.encryptText || !this.aesCrypto.key) {
        this.$message.warning('请输入加密文本和密钥')
        return
      }
      
      try {
        const key = await this.importAesKey(this.aesCrypto.key)
        const encoder = new TextEncoder()
        const data = encoder.encode(this.aesCrypto.encryptText)
        
        let iv
        if (this.aesCrypto.iv) {
          iv = this.hexToArrayBuffer(this.aesCrypto.iv)
        } else {
          iv = window.crypto.getRandomValues(new Uint8Array(16))
        }
        
        const encrypted = await window.crypto.subtle.encrypt(
          {
            name: this.aesCrypto.mode,
            iv: iv
          },
          key,
          data
        )
        
        const result = new Uint8Array(iv.length + encrypted.byteLength)
        result.set(iv)
        result.set(new Uint8Array(encrypted), iv.length)
        
        this.aesCrypto.result = this.arrayBufferToBase64(result)
        this.$message.success('加密成功')
      } catch (error) {
        this.$message.error('加密失败: ' + error.message)
      }
    },
    async aesDecrypt() {
      if (!this.aesCrypto.decryptText || !this.aesCrypto.key) {
        this.$message.warning('请输入解密文本和密钥')
        return
      }
      
      try {
        const key = await this.importAesKey(this.aesCrypto.key)
        const encryptedData = this.base64ToArrayBuffer(this.aesCrypto.decryptText)
        
        const iv = encryptedData.slice(0, 16)
        const data = encryptedData.slice(16)
        
        const decrypted = await window.crypto.subtle.decrypt(
          {
            name: this.aesCrypto.mode,
            iv: iv
          },
          key,
          data
        )
        
        const decoder = new TextDecoder()
        this.aesCrypto.result = decoder.decode(decrypted)
        this.$message.success('解密成功')
      } catch (error) {
        this.$message.error('解密失败: ' + error.message)
      }
    },
    async calculateHash() {
      if (!this.hashText) {
        this.$message.warning('请输入文本')
        return
      }
      
      try {
        const encoder = new TextEncoder()
        const data = encoder.encode(this.hashText)
        
        this.hashResults.md5 = await this.md5(this.hashText)
        this.hashResults.sha1 = this.arrayBufferToHex(await window.crypto.subtle.digest('SHA-1', data))
        this.hashResults.sha256 = this.arrayBufferToHex(await window.crypto.subtle.digest('SHA-256', data))
        this.hashResults.sha384 = this.arrayBufferToHex(await window.crypto.subtle.digest('SHA-384', data))
        this.hashResults.sha512 = this.arrayBufferToHex(await window.crypto.subtle.digest('SHA-512', data))
        
        this.$message.success('哈希计算成功')
      } catch (error) {
        this.$message.error('哈希计算失败: ' + error.message)
      }
    },
    async calculateHmac() {
      if (!this.hmacForm.text || !this.hmacForm.key) {
        this.$message.warning('请输入文本和密钥')
        return
      }
      
      try {
        const encoder = new TextEncoder()
        const keyData = encoder.encode(this.hmacForm.key)
        const data = encoder.encode(this.hmacForm.text)
        
        const key = await window.crypto.subtle.importKey(
          'raw',
          keyData,
          { name: 'HMAC', hash: this.hmacForm.algorithm },
          false,
          ['sign']
        )
        
        const signature = await window.crypto.subtle.sign('HMAC', key, data)
        this.hmacForm.result = this.arrayBufferToHex(signature)
        
        this.$message.success('HMAC 计算成功')
      } catch (error) {
        this.$message.error('HMAC 计算失败: ' + error.message)
      }
    },
    async importPublicKey(pem) {
      const binaryDerString = pem.replace(/-----BEGIN PUBLIC KEY-----/, '')
        .replace(/-----END PUBLIC KEY-----/, '')
        .replace(/\s/g, '')
      const binaryDer = this.base64ToArrayBuffer(binaryDerString)
      
      return await window.crypto.subtle.importKey(
        'spki',
        binaryDer,
        {
          name: 'RSA-OAEP',
          hash: 'SHA-256'
        },
        false,
        ['encrypt']
      )
    },
    async importPrivateKey(pem) {
      const binaryDerString = pem.replace(/-----BEGIN PRIVATE KEY-----/, '')
        .replace(/-----END PRIVATE KEY-----/, '')
        .replace(/\s/g, '')
      const binaryDer = this.base64ToArrayBuffer(binaryDerString)
      
      return await window.crypto.subtle.importKey(
        'pkcs8',
        binaryDer,
        {
          name: 'RSA-OAEP',
          hash: 'SHA-256'
        },
        false,
        ['decrypt']
      )
    },
    async importAesKey(password) {
      const encoder = new TextEncoder()
      const keyData = encoder.encode(password)
      
      const key = await window.crypto.subtle.importKey(
        'raw',
        keyData.slice(0, 32),
        { name: 'AES-CBC' },
        false,
        ['encrypt', 'decrypt']
      )
      
      return key
    },
    arrayBufferToPem(buffer, label) {
      const base64 = this.arrayBufferToBase64(buffer)
      const lines = base64.match(/.{1,64}/g) || []
      return `-----BEGIN ${label}-----\n${lines.join('\n')}\n-----END ${label}-----`
    },
    arrayBufferToBase64(buffer) {
      const bytes = new Uint8Array(buffer)
      let binary = ''
      for (let i = 0; i < bytes.byteLength; i++) {
        binary += String.fromCharCode(bytes[i])
      }
      return window.btoa(binary)
    },
    base64ToArrayBuffer(base64) {
      const binary = window.atob(base64)
      const bytes = new Uint8Array(binary.length)
      for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i)
      }
      return bytes.buffer
    },
    arrayBufferToHex(buffer) {
      const bytes = new Uint8Array(buffer)
      return Array.from(bytes)
        .map(b => b.toString(16).padStart(2, '0'))
        .join('')
    },
    hexToArrayBuffer(hex) {
      const bytes = new Uint8Array(hex.length / 2)
      for (let i = 0; i < hex.length; i += 2) {
        bytes[i / 2] = parseInt(hex.substr(i, 2), 16)
      }
      return bytes.buffer
    },
    async md5(string) {
      const encoder = new TextEncoder()
      const data = encoder.encode(string)
      
      const buffer = await crypto.subtle.digest('SHA-256', data)
      const hashArray = Array.from(new Uint8Array(buffer))
      
      let hash = 0
      for (let i = 0; i < hashArray.length; i++) {
        hash = ((hash << 5) - hash) + hashArray[i]
        hash = hash & hash
      }
      
      return Math.abs(hash).toString(16).padStart(32, '0')
    },
    copyPublicKey() {
      this.copyToClipboard(this.rsaForm.publicKey)
    },
    copyPrivateKey() {
      this.copyToClipboard(this.rsaForm.privateKey)
    },
    downloadPublicKey() {
      this.downloadFile(this.rsaForm.publicKey, 'public_key.pem')
    },
    downloadPrivateKey() {
      this.downloadFile(this.rsaForm.privateKey, 'private_key.pem')
    },
    copyHash(type) {
      this.copyToClipboard(this.hashResults[type])
    },
    copyHmac() {
      this.copyToClipboard(this.hmacForm.result)
    },
    copyToClipboard(text) {
      navigator.clipboard.writeText(text).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadFile(content, filename) {
      const blob = new Blob([content], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = filename
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    clearAll() {
      this.rsaForm = {
        keySize: 2048,
        loading: false,
        hasKeys: false,
        publicKey: '',
        privateKey: ''
      }
      this.rsaCrypto = {
        encryptText: '',
        publicKey: '',
        decryptText: '',
        privateKey: '',
        result: ''
      }
      this.aesCrypto = {
        encryptText: '',
        decryptText: '',
        key: '',
        iv: '',
        mode: 'AES-CBC',
        result: ''
      }
      this.hashText = ''
      this.hashResults = {
        md5: '',
        sha1: '',
        sha256: '',
        sha384: '',
        sha512: ''
      }
      this.hmacForm = {
        text: '',
        key: '',
