<template>
  <div class="csv-editor-tool">
    <el-card>
      <div slot="header">
        <span>CSV 编辑器</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
          <el-button size="small" @click="importCsv" type="primary">导入</el-button>
          <el-button size="small" @click="exportCsv" type="success">导出</el-button>
        </el-button-group>
      </div>

      <el-upload
        class="uploader"
        :auto-upload="false"
        :show-file-list="false"
        :on-change="handleFileChange"
        accept=".csv"
      >
        <el-button size="small" type="info">
          <i class="el-icon-upload2"></i> 选择 CSV 文件
        </el-button>
      </el-upload>

      <div class="editor-container">
        <el-table
          :data="csvData"
          border
          style="width: 100%"
        >
          <el-table-column
            v-for="(header, index) in headers"
            :key="index"
            :prop="`col${index}`"
            :label="header"
            min-width="120"
          >
            <template slot-scope="scope">
              <el-input
                v-model="scope.row[`col${index}`]"
                size="small"
                @change="updateCsv"
              />
            </template>
          </el-table-column>
          <el-table-column label="操作" width="120">
            <template slot-scope="scope">
              <el-button
                size="mini"
                type="danger"
                @click="removeRow(scope.$index)"
              >
                删除
              </el-button>
            </template>
          </el-table-column>
        </el-table>

        <div class="table-actions">
          <el-button @click="addRow" type="primary" size="small">
            <i class="el-icon-plus"></i> 添加行
          </el-button>
          <el-button @click="addColumn" type="primary" size="small">
            <i class="el-icon-plus"></i> 添加列
          </el-button>
          <el-button @click="removeColumn" type="danger" size="small" :disabled="headers.length <= 1">
            <i class="el-icon-minus"></i> 删除列
          </el-button>
        </div>
      </div>

      <div class="preview-container" style="margin-top: 20px">
        <el-card shadow="hover">
          <div slot="header">
            <span>CSV 预览</span>
            <el-button size="small" @click="copyCsv" type="primary">复制</el-button>
          </div>
          <el-input
            type="textarea"
            :rows="10"
            :value="csvContent"
            readonly
            class="code-area"
          />
        </el-card>
      </div>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CsvEditorTool',
  data() {
    return {
      headers: ['Name', 'Age', 'Email'],
      csvData: [
        { col0: 'John Doe', col1: '30', col2: 'john@example.com' },
        { col0: 'Jane Smith', col1: '25', col2: 'jane@example.com' },
        { col0: 'Bob Johnson', col1: '35', col2: 'bob@example.com' }
      ]
    }
  },
  computed: {
    csvContent() {
      // 生成 CSV 内容
      const headerRow = this.headers.join(',')
      const dataRows = this.csvData.map(row => {
        return this.headers.map((_, index) => {
          const value = row[`col${index}`] || ''
          // 处理包含逗号或引号的值
          if (value.includes(',') || value.includes('"') || value.includes('\n')) {
            return `"${value.replace(/"/g, '""')}"`
          }
          return value
        }).join(',')
      })
      return [headerRow, ...dataRows].join('\n')
    }
  },
  methods: {
    clearAll() {
      this.headers = ['Column 1', 'Column 2']
      this.csvData = [
        { col0: '', col1: '' },
        { col0: '', col1: '' }
      ]
    },
    addRow() {
      const newRow = {}
      this.headers.forEach((_, index) => {
        newRow[`col${index}`] = ''
      })
      this.csvData.push(newRow)
    },
    removeRow(index) {
      this.csvData.splice(index, 1)
    },
    addColumn() {
      const newColIndex = this.headers.length
      this.headers.push(`Column ${newColIndex + 1}`)
      this.csvData.forEach(row => {
        row[`col${newColIndex}`] = ''
      })
    },
    removeColumn() {
      if (this.headers.length > 1) {
        const lastColIndex = this.headers.length - 1
        this.headers.pop()
        this.csvData.forEach(row => {
          delete row[`col${lastColIndex}`]
        })
      }
    },
    updateCsv() {
      // 可以在这里添加额外的更新逻辑
    },
    handleFileChange(file) {
      const reader = new FileReader()
      reader.onload = (e) => {
        this.parseCsv(e.target.result)
      }
      reader.readAsText(file.raw)
    },
    parseCsv(csvText) {
      const lines = csvText.split(/\r?\n/).filter(line => line.trim())
      if (lines.length === 0) return

      // 解析表头
      this.headers = this.parseCsvLine(lines[0])

      // 解析数据
      this.csvData = []
      for (let i = 1; i < lines.length; i++) {
        const values = this.parseCsvLine(lines[i])
        const row = {}
        this.headers.forEach((_, index) => {
          row[`col${index}`] = values[index] || ''
        })
        this.csvData.push(row)
      }
    },
    parseCsvLine(line) {
      const result = []
      let current = ''
      let inQuotes = false
      let escapeNext = false

      for (let i = 0; i < line.length; i++) {
        const char = line[i]

        if (escapeNext) {
          current += char
          escapeNext = false
        } else if (char === '"') {
          inQuotes = !inQuotes
        } else if (char === ',' && !inQuotes) {
          result.push(current)
          current = ''
        } else if (char === '\\') {
          escapeNext = true
        } else {
          current += char
        }
      }

      result.push(current)
      return result
    },
    importCsv() {
      const input = document.createElement('input')
      input.type = 'file'
      input.accept = '.csv'
      input.onchange = (e) => {
        const file = e.target.files[0]
        if (file) {
          const reader = new FileReader()
          reader.onload = (e) => {
            this.parseCsv(e.target.result)
          }
          reader.readAsText(file)
        }
      }
      input.click()
    },
    exportCsv() {
      const blob = new Blob([this.csvContent], { type: 'text/csv;charset=utf-8;' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.setAttribute('download', `data_${new Date().toISOString().slice(0, 10)}.csv`)
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
    },
    copyCsv() {
      this.$copyText(this.csvContent).then(() => {
        this.$message.success('CSV 内容已复制到剪贴板')
      })
    }
  }
}
</script>

