<template>
  <div class="image-tool">
    <el-card>
      <div slot="header">
        <span>图片处理工具</span>
      </div>

      <el-upload
        class="upload-area"
        drag
        action=""
        :auto-upload="false"
        :on-change="handleFileChange"
        :show-file-list="false"
        accept="image/*"
      >
        <i class="el-icon-upload"></i>
        <div class="el-upload__text">将图片拖到此处，或<em>点击上传</em></div>
        <div class="el-upload__tip" slot="tip">支持 JPG、PNG、GIF、WebP 格式</div>
      </el-upload>

      <template v-if="imageUrl">
        <el-divider>图片预览</el-divider>
        
        <el-row :gutter="20">
          <el-col :span="16">
            <div class="image-preview">
              <canvas ref="canvas" class="preview-canvas"></canvas>
            </div>
          </el-col>
          <el-col :span="8">
            <div class="image-info">
              <h4>图片信息</h4>
              <p>文件名: {{ fileName }}</p>
              <p>原始尺寸: {{ originalWidth }} x {{ originalHeight }} px</p>
              <p>当前尺寸: {{ currentWidth }} x {{ currentHeight }} px</p>
              <p>文件大小: {{ formatFileSize(fileSize) }}</p>
            </div>
          </el-col>
        </el-row>

        <el-divider>处理选项</el-divider>

        <el-tabs v-model="activeTab">
          <el-tab-pane label="压缩" name="compress">
            <el-form :model="compressOptions" label-width="120px">
              <el-form-item label="压缩质量">
                <el-slider v-model="compressOptions.quality" :min="1" :max="100" show-input />
              </el-form-item>
              <el-form-item label="输出格式">
                <el-radio-group v-model="compressOptions.format">
                  <el-radio-button label="original">原格式</el-radio-button>
                  <el-radio-button label="jpeg">JPEG</el-radio-button>
                  <el-radio-button label="png">PNG</el-radio-button>
                  <el-radio-button label="webp">WebP</el-radio-button>
                </el-radio-group>
              </el-form-item>
              <el-form-item>
                <el-button type="primary" @click="compressImage">压缩</el-button>
              </el-form-item>
            </el-form>
          </el-tab-pane>

          <el-tab-pane label="裁剪" name="crop">
            <el-form :model="cropOptions" label-width="120px">
              <el-row :gutter="10">
                <el-col :span="12">
                  <el-form-item label="起始X">
                    <el-input-number v-model="cropOptions.x" :min="0" :max="originalWidth" style="width: 100%" />
                  </el-form-item>
                </el-col>
                <el-col :span="12">
                  <el-form-item label="起始Y">
                    <el-input-number v-model="cropOptions.y" :min="0" :max="originalHeight" style="width: 100%" />
                  </el-form-item>
                </el-col>
              </el-row>
              <el-row :gutter="10">
                <el-col :span="12">
                  <el-form-item label="宽度">
                    <el-input-number v-model="cropOptions.width" :min="1" :max="originalWidth" style="width: 100%" />
                  </el-form-item>
                </el-col>
                <el-col :span="12">
                  <el-form-item label="高度">
                    <el-input-number v-model="cropOptions.height" :min="1" :max="originalHeight" style="width: 100%" />
                  </el-form-item>
                </el-col>
              </el-row>
              <el-form-item>
                <el-button type="primary" @click="cropImage">裁剪</el-button>
                <el-button @click="resetCrop">重置</el-button>
              </el-form-item>
            </el-form>
          </el-tab-pane>

          <el-tab-pane label="缩放" name="resize">
            <el-form :model="resizeOptions" label-width="120px">
              <el-form-item label="缩放方式">
                <el-radio-group v-model="resizeOptions.mode">
                  <el-radio-button label="percent">百分比</el-radio-button>
                  <el-radio-button label="pixel">像素</el-radio-button>
                </el-radio-group>
              </el-form-item>
              <template v-if="resizeOptions.mode === 'percent'">
                <el-form-item label="缩放比例">
                  <el-slider v-model="resizeOptions.percent" :min="1" :max="200" show-input />
                </el-form-item>
              </template>
              <template v-else>
                <el-row :gutter="10">
                  <el-col :span="12">
                    <el-form-item label="宽度">
                      <el-input-number v-model="resizeOptions.width" :min="1" :max="5000" style="width: 100%" />
                    </el-form-item>
                  </el-col>
                  <el-col :span="12">
                    <el-form-item label="高度">
                      <el-input-number v-model="resizeOptions.height" :min="1" :max="5000" style="width: 100%" />
                    </el-form-item>
                  </el-col>
                </el-row>
              </template>
              <el-form-item label="保持比例">
                <el-switch v-model="resizeOptions.maintainRatio" />
              </el-form-item>
              <el-form-item>
                <el-button type="primary" @click="resizeImage">缩放</el-button>
              </el-form-item>
            </el-form>
          </el-tab-pane>

          <el-tab-pane label="旋转" name="rotate">
            <el-form :model="rotateOptions" label-width="120px">
              <el-form-item label="旋转角度">
                <el-radio-group v-model="rotateOptions.angle">
                  <el-radio-button :label="0">0°</el-radio-button>
                  <el-radio-button :label="90">90°</el-radio-button>
                  <el-radio-button :label="180">180°</el-radio-button>
                  <el-radio-button :label="270">270°</el-radio-button>
                </el-radio-group>
              </el-form-item>
              <el-form-item label="自定义角度">
                <el-slider v-model="rotateOptions.customAngle" :min="0" :max="360" show-input />
              </el-form-item>
              <el-form-item>
                <el-button type="primary" @click="rotateImage">旋转</el-button>
              </el-form-item>
            </el-form>
          </el-tab-pane>

          <el-tab-pane label="滤镜" name="filter">
            <el-form :model="filterOptions" label-width="120px">
              <el-form-item label="灰度">
                <el-slider v-model="filterOptions.grayscale" :max="100" />
              </el-form-item>
              <el-form-item label="亮度">
                <el-slider v-model="filterOptions.brightness" :min="0" :max="200" />
              </el-form-item>
              <el-form-item label="对比度">
                <el-slider v-model="filterOptions.contrast" :min="0" :max="200" />
              </el-form-item>
              <el-form-item label="饱和度">
                <el-slider v-model="filterOptions.saturate" :min="0" :max="200" />
              </el-form-item>
              <el-form-item label="模糊">
                <el-slider v-model="filterOptions.blur" :max="10" :step="0.5" />
              </el-form-item>
              <el-form-item>
                <el-button type="primary" @click="applyFilter">应用滤镜</el-button>
                <el-button @click="resetFilter">重置</el-button>
              </el-form-item>
            </el-form>
          </el-tab-pane>
        </el-tabs>

        <div class="action-buttons">
          <el-button type="success" @click="downloadImage">下载图片</el-button>
          <el-button @click="resetImage">重置图片</el-button>
          <el-button type="danger" @click="clearImage">清除</el-button>
        </div>
      </template>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'ImageTool',
  data() {
    return {
      imageUrl: null,
      fileName: '',
      fileSize: 0,
      originalWidth: 0,
      originalHeight: 0,
      currentWidth: 0,
      currentHeight: 0,
      activeTab: 'compress',
      image: null,
      compressOptions: {
        quality: 80,
        format: 'original'
      },
      cropOptions: {
        x: 0,
        y: 0,
        width: 0,
        height: 0
      },
      resizeOptions: {
        mode: 'percent',
        percent: 100,
        width: 0,
        height: 0,
        maintainRatio: true
      },
      rotateOptions: {
        angle: 0,
        customAngle: 0
      },
      filterOptions: {
        grayscale: 0,
        brightness: 100,
        contrast: 100,
        saturate: 100,
        blur: 0
      }
    }
  },
  methods: {
    handleFileChange(file) {
      if (!file.raw) return
      
      this.fileName = file.name
      this.fileSize = file.size
      
      const reader = new FileReader()
      reader.onload = (e) => {
        this.imageUrl = e.target.result
        this.loadImage()
      }
      reader.readAsDataURL(file.raw)
    },
    loadImage() {
      this.image = new Image()
      this.image.onload = () => {
        this.originalWidth = this.image.width
        this.originalHeight = this.image.height
        this.currentWidth = this.image.width
        this.currentHeight = this.image.height
        this.cropOptions.width = this.image.width
        this.cropOptions.height = this.image.height
        this.resizeOptions.width = this.image.width
        this.resizeOptions.height = this.image.height
        this.drawImage()
      }
      this.image.src = this.imageUrl
    },
    drawImage() {
      const canvas = this.$refs.canvas
      canvas.width = this.currentWidth
      canvas.height = this.currentHeight
      const ctx = canvas.getContext('2d')
      ctx.drawImage(this.image, 0, 0, this.currentWidth, this.currentHeight)
    },
    compressImage() {
      const canvas = this.$refs.canvas
      let mimeType = 'image/jpeg'
      
      if (this.compressOptions.format === 'png') {
        mimeType = 'image/png'
      } else if (this.compressOptions.format === 'webp') {
        mimeType = 'image/webp'
      } else if (this.compressOptions.format === 'original') {
        mimeType = this.getMimeTypeFromFileName(this.fileName)
      }
      
      const quality = this.compressOptions.quality / 100
      const compressedDataUrl = canvas.toDataURL(mimeType, quality)
      
      // Update image with compressed version
      this.image = new Image()
      this.image.onload = () => {
        this.drawImage()
        this.$message.success('图片已压缩')
      }
      this.image.src = compressedDataUrl
    },
    cropImage() {
      const canvas = document.createElement('canvas')
      canvas.width = this.cropOptions.width
      canvas.height = this.cropOptions.height
      const ctx = canvas.getContext('2d')
      
      ctx.drawImage(
        this.image,
        this.cropOptions.x,
        this.cropOptions.y,
        this.cropOptions.width,
        this.cropOptions.height,
        0,
        0,
        this.cropOptions.width,
        this.cropOptions.height
      )
      
      this.currentWidth = this.cropOptions.width
      this.currentHeight = this.cropOptions.height
      this.image = new Image()
      this.image.onload = () => {
        this.drawImage()
        this.$message.success('图片已裁剪')
      }
      this.image.src = canvas.toDataURL()
    },
    resetCrop() {
      this.cropOptions.x = 0
      this.cropOptions.y = 0
      this.cropOptions.width = this.currentWidth
      this.cropOptions.height = this.currentHeight
    },
    resizeImage() {
      let newWidth, newHeight
      
      if (this.resizeOptions.mode === 'percent') {
        const ratio = this.resizeOptions.percent / 100
        newWidth = Math.round(this.currentWidth * ratio)
        newHeight = Math.round(this.currentHeight * ratio)
      } else {
        newWidth = this.resizeOptions.width
        if (this.resizeOptions.maintainRatio) {
          const ratio = newWidth / this.currentWidth
          newHeight = Math.round(this.currentHeight * ratio)
        } else {
          newHeight = this.resizeOptions.height
        }
      }
      
      const canvas = document.createElement('canvas')
      canvas.width = newWidth
      canvas.height = newHeight
      const ctx = canvas.getContext('2d')
      
      ctx.drawImage(this.image, 0, 0, newWidth, newHeight)
      
      this.currentWidth = newWidth
      this.currentHeight = newHeight
      this.image = new Image()
      this.image.onload = () => {
        this.drawImage()
        this.$message.success('图片已缩放')
      }
      this.image.src = canvas.toDataURL()
    },
    rotateImage() {
      const angle = this.rotateOptions.customAngle || this.rotateOptions.angle
      const radians = (angle * Math.PI) / 180
      
      const canvas = document.createElement('canvas')
      const sin = Math.abs(Math.sin(radians))
      const cos = Math.abs(Math.cos(radians))
      
      canvas.width = this.currentWidth * cos + this.currentHeight * sin
      canvas.height = this.currentWidth * sin + this.currentHeight * cos
      
      const ctx = canvas.getContext('2d')
      ctx.translate(canvas.width / 2, canvas.height / 2)
      ctx.rotate(radians)
      ctx.drawImage(this.image, -this.currentWidth / 2, -this.currentHeight / 2)
      
      this.currentWidth = canvas.width
      this.currentHeight = canvas.height
      this.image = new Image()
      this.image.onload = () => {
        this.drawImage()
        this.$message.success('图片已旋转')
      }
      this.image.src = canvas.toDataURL()
    },
    applyFilter() {
      const canvas = this.$refs.canvas
      const ctx = canvas.getContext('2d')
      
      ctx.filter = `
        grayscale(${this.filterOptions.grayscale}%) 
        brightness(${this.filterOptions.brightness}%) 
        contrast(${this.filterOptions.contrast}%) 
        saturate(${this.filterOptions.saturate}%) 
        blur(${this.filterOptions.blur}px)
      `
      
      ctx.drawImage(this.image, 0, 0, this.currentWidth, this.currentHeight)
      ctx.filter = 'none'
      
      this.$message.success('滤镜已应用')
    },
    resetFilter() {
      this.filterOptions = {
        grayscale: 0,
        brightness: 100,
        contrast: 100,
        saturate: 100,
        blur: 0
      }
      this.drawImage()
    },
    downloadImage() {
      const canvas = this.$refs.canvas
      const link = document.createElement('a')
      link.download = `processed_${this.fileName}`
      link.href = canvas.toDataURL('image/png')
      link.click()
    },
    resetImage() {
      if (this.imageUrl) {
        this.loadImage()
        this.$message.success('图片已重置')
      }
    },
    clearImage() {
      this.imageUrl = null
      this.image = null
      this.fileName = ''
      this.fileSize = 0
      this.originalWidth = 0
      this.originalHeight = 0
      this.currentWidth = 0
      this.currentHeight = 0
    },
    getMimeTypeFromFileName(fileName) {
      const ext = fileName.split('.').pop().toLowerCase()
      const mimeTypes = {
        'jpg': 'image/jpeg',
        'jpeg': 'image/jpeg',
        'png': 'image/png',
        'gif': 'image/gif',
        'webp': 'image/webp'
      }
      return mimeTypes[ext] || 'image/jpeg'
    },
    formatFileSize(bytes) {
      if (bytes === 0) return '0 B'
      const k = 1024
      const sizes = ['B', 'KB', 'MB']
      const i = Math.floor(Math.log(bytes) / Math.log(k))
      return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
    }
  }
}
</script>

<style scoped>
.image-tool {
  padding: 20px;
}

.upload-area {
  text-align: center;
}

.image-preview {
  border: 1px solid #dcdfe6;
  border-radius: 4px;
  padding: 10px;
  background: #f5f7fa;
  text-align: center;
}

.preview-canvas {
  max-width: 100%;
  max-height: 400px;
  border: 1px solid #dcdfe6;
}

.image-info {
  padding: 15px;
  background: #f5f7fa;
  border-radius: 4px;
}

.image-info h4 {
  margin-top: 0;
  margin-bottom: 15px;
  color: #303133;
}

.image-info p {
  margin: 8px 0;
  color: #606266;
  font-size: 14px;
}

.action-buttons {
  text-align: center;
  margin-top: 20px;
}
</style>
