export default {
  name: 'PinyinTool',
  data() {
    return {
      inputText: '',
      outputText: '',
      options: {
        firstLetter: false,
        uppercase: false,
        separator: ' '
      }
    }
  },
  methods: {
    convert() {
      if (!this.inputText.trim()) {
        this.$message.warning('请输入文本')
        return
      }

      const chars = this.inputText.split('')
      const pinyins = []

      for (const char of chars) {
        const pinyin = pinyinMap[char]
        if (pinyin) {
          let result = this.options.firstLetter ? pinyin[0] : pinyin
          if (this.options.uppercase) {
            result = result.toUpperCase()
          }
          pinyins.push(result)
        } else {
          pinyins.push(char)
        }
      }

      this.outputText = pinyins.join(this.options.separator)
      this.$message.success('转换完成')
    },
    copyResult() {
      if (!this.outputText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.outputText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    loadExample() {
      this.inputText = '你好世界，欢迎使用拼音转换工具'
    },
    clear() {
      this.inputText = ''
      this.outputText = ''
    }
  }
}
