<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Unicode 转换</span>
        <el-button size="small" @click="clearAll">清空</el-button>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="11">
          <div class="input-section">
            <div class="section-header">
              <span>文本</span>
              <el-tag size="mini" type="primary">输入或输出</el-tag>
            </div>
            <el-input
              v-model="text"
              type="textarea"
              :rows="8"
              placeholder="输入文本"
            />
          </div>
        </el-col>
        
        <el-col :span="2" class="actions-col">
          <div class="action-buttons">
            <el-button type="primary" circle @click="textToUnicode" title="文本 → Unicode">
              <i class="el-icon-right"></i>
            </el-button>
            <span class="action-label">编码</span>
            <el-button type="success" circle @click="unicodeToText" title="Unicode → 文本">
              <i class="el-icon-back"></i>
            </el-button>
            <span class="action-label">解码</span>
          </div>
        </el-col>
        
        <el-col :span="11">
          <div class="output-section">
            <div class="section-header">
              <span>Unicode</span>
              <el-tag size="mini" type="success">输入或输出</el-tag>
            </div>
            <el-input
              v-model="unicode"
              type="textarea"
              :rows="8"
              placeholder="Unicode 编码 (如: \u4e2d\u6587)"
            />
          </div>
        </el-col>
      </el-row>

      <el-divider>转换选项</el-divider>

      <el-row>
        <el-col :span="24">
          <el-radio-group v-model="format">
            <el-radio label="escape">\uXXXX 格式</el-radio>
            <el-radio label="html">&#XXXXX; HTML 格式</el-radio>
            <el-radio label="decimal">十进制</el-radio>
            <el-radio label="name">U+XXXX 格式</el-radio>
          </el-radio-group>
        </el-col>
      </el-row>

      <el-row v-if="charDetails.length > 0" style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">字符详情</div>
            <el-table :data="charDetails" border size="small" max-height="300">
              <el-table-column prop="char" label="字符" width="80" align="center" />
              <el-table-column prop="unicode" label="Unicode" width="120" />
              <el-table-column prop="decimal" label="十进制" width="100" />
              <el-table-column prop="html" label="HTML" width="120" />
              <el-table-column prop="name" label="名称" />
            </el-table>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'UnicodeTool',
  data() {
    return {
      text: '',
      unicode: '',
      format: 'escape',
      charDetails: []
    }
  },
  methods: {
    textToUnicode() {
      if (!this.text) {
        this.unicode = ''
        this.charDetails = []
        return
      }
      
      const details = []
      let result = ''
      
      for (const char of this.text) {
        const code = char.codePointAt(0)
        
        switch (this.format) {
          case 'escape':
            result += `\\u${code.toString(16).padStart(4, '0')}`
            break
          case 'html':
            result += `&#${code};`
            break
          case 'decimal':
            result += code.toString()
            break
          case 'name':
            result += `U+${code.toString(16).toUpperCase().padStart(4, '0')}`
            break
        }
        
        details.push({
          char,
          unicode: `U+${code.toString(16).toUpperCase().padStart(4, '0')}`,
          decimal: code,
          html: `&#${code};`,
          name: this.getCharName(char)
        })
      }
      
      this.unicode = result
      this.charDetails = details
    },
    unicodeToText() {
      if (!this.unicode) {
        this.text = ''
        return
      }
      
      try {
        // 尝试解析各种格式
        let result = this.unicode
        
        // \uXXXX 格式
        result = result.replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) => 
          String.fromCharCode(parseInt(hex, 16))
        )
        
        // &#XXXXX; HTML 格式
        result = result.replace(/&#(\d+);/g, (_, dec) => 
          String.fromCharCode(parseInt(dec, 10))
        )
        
        // U+XXXX 格式
        result = result.replace(/U\+([0-9a-fA-F]{4,6})/gi, (_, hex) => 
          String.fromCharCode(parseInt(hex, 16))
        )
        
        this.text = result
        this.textToUnicode()
      } catch (e) {
        this.$message.error('解码失败: ' + e.message)
      }
    },
    getCharName(char) {
      const names = {
        ' ': '空格',
        '\n': '换行',
        '\t': '制表符'
      }
      return names[char] || '-'
    },
    clearAll() {
      this.text = ''
      this.unicode = ''
      this.charDetails = []
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .input-section, .output-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }

  .actions-col {
    display: flex;
    align-items: center;
    justify-content: center;

    .action-buttons {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 10px;

      .action-label {
        font-size: 12px;
        color: #606266;
        margin-bottom: 10px;
      }
    }
  }
}
</style>
