<template>
  <div class="home">
    <!-- 紧凑统计栏 + 快捷操作 -->
    <div class="stats-bar">
      <div class="stats-left">
        <h1 class="stats-title">IT Tools</h1>
        <p class="stats-desc">纯前端工具集 · {{ activeCategories.length }} 个分类 · {{ visibleTools.length }} 个工具</p>
      </div>
      <div class="stats-right">
        <span class="quick-label">快捷入口</span>
        <el-button size="small" round @click="copyTimestamp" :title="'点击复制: ' + currentTimestamp">
          <i class="el-icon-time"></i> 时间戳
        </el-button>
        <el-button size="small" round @click="copyUuid">
          <i class="el-icon-key"></i> UUID
        </el-button>
        <el-button size="small" round @click="goToJson">
          <i class="el-icon-document"></i> JSON
        </el-button>
        <el-button size="small" round @click="goToBase64">
          <i class="el-icon-lock"></i> Base64
        </el-button>
      </div>
    </div>

    <!-- 搜索栏 -->
    <div class="search-container">
      <el-input
        v-model="searchKeyword"
        placeholder="搜索工具名称或描述..."
        prefix-icon="el-icon-search"
        size="large"
        clearable
        @input="handleSearch"
      />
      <div v-if="searchKeyword && filteredTools.length > 0" class="search-results">
        <div
          v-for="tool in filteredTools"
          :key="tool.path"
          class="search-item"
          @click="goToTool(tool)"
        >
          <i :class="tool.icon"></i>
          <div class="tool-info">
            <span class="tool-name">{{ tool.name }}</span>
            <span class="tool-desc">{{ tool.desc }}</span>
          </div>
          <el-tag size="mini" type="info">{{ tool.category }}</el-tag>
        </div>
      </div>
      <div v-if="searchKeyword && filteredTools.length === 0" class="no-results">
        <i class="el-icon-search"></i>
        <p>未找到匹配的工具</p>
      </div>
    </div>

    <!-- 分类卡片 - 自动流式布局 -->
    <el-row :gutter="20">
      <el-col v-for="cat in activeCategories" :key="cat.name" :span="24" style="margin-bottom: 20px">
        <el-card class="category-card" shadow="hover">
          <div slot="header" class="card-header">
            <div class="card-header-left">
              <i :class="cat.icon"></i>
              <span>{{ cat.name }}</span>
            </div>
            <el-tag size="mini" type="info">{{ cat.tools.length }} 个</el-tag>
          </div>
          <div class="tool-list">
            <router-link
              v-for="(tool, i) in cat.tools"
              :key="tool.path"
              :to="tool.path"
              class="tool-item"
              :style="toolColor(i)"
            >{{ tool.name }}</router-link>
            <div v-if="cat.tools.length === 0" class="tool-empty">暂无工具</div>
          </div>
        </el-card>
      </el-col>
    </el-row>
  </div>
</template>

<script>
import { allTools, categoryMeta, searchTools } from '@/data/tools'

export default {
  name: 'Home',
  data() {
    return {
      currentTimestamp: '',
      currentUuid: '',
      searchKeyword: '',
      filteredTools: [],
      backendAvailable: false,
      checkingBackend: true,
      toolColorPalette: [
        { bg: '#ecf5ff', border: '#b3d8ff', text: '#409EFF' },
        { bg: '#f0f9eb', border: '#c2e7b0', text: '#67C23A' },
        { bg: '#fdf6ec', border: '#f5dab1', text: '#E6A23C' },
        { bg: '#fef0f0', border: '#fbc4c4', text: '#F56C6C' },
        { bg: '#f4f4f5', border: '#c8c9cc', text: '#909399' },
        { bg: '#f0f5ff', border: '#b3c6ff', text: '#5470C6' },
        { bg: '#e8f4fd', border: '#a3d5f5', text: '#06AED5' },
        { bg: '#f5f0ff', border: '#d4b8ff', text: '#8B5CF6' },
      ],
    }
  },
  computed: {
    allTools() {
      return allTools
    },
    categoryMeta() {
      return categoryMeta
    },
    visibleTools() {
      if (this.backendAvailable) {
        return this.allTools
      }
      return this.allTools.filter(tool => !tool.needBackend)
    },
    activeCategories() {
      return this.categoryMeta
        .map(cat => ({
          ...cat,
          tools: this.visibleTools.filter(t => t.category === cat.name)
        }))
        .filter(cat => cat.tools.length > 0)
    }
  },
  async mounted() {
    await this.checkBackendAvailability()
    this.updateQuickActions()
    setInterval(this.updateQuickActions, 1000)
  },
  methods: {
    async checkBackendAvailability() {
      try {
        const controller = new AbortController()
        const timeoutId = setTimeout(() => controller.abort(), 3000)
        const response = await fetch('/api/ping', {
          method: 'GET',
          signal: controller.signal
        })
        clearTimeout(timeoutId)
        this.backendAvailable = response.ok
      } catch (e) {
        this.backendAvailable = false
      } finally {
        this.checkingBackend = false
      }
    },
    handleSearch() {
      this.filteredTools = searchTools(this.searchKeyword, this.visibleTools, { limit: 12 })
    },
    goToTool(tool) {
      this.searchKeyword = ''
      this.filteredTools = []
      this.$router.push(tool.path)
    },
    updateQuickActions() {
      this.currentTimestamp = Date.now().toString()
      if (!this.currentUuid) {
        this.currentUuid = this.generateUuid()
      }
    },
    generateUuid() {
      return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        const r = Math.random() * 16 | 0
        const v = c === 'x' ? r : (r & 0x3 | 0x8)
        return v.toString(16)
      })
    },
    copyTimestamp() {
      navigator.clipboard.writeText(this.currentTimestamp).then(() => {
        this.$message.success('时间戳已复制: ' + this.currentTimestamp)
      })
    },
    copyUuid() {
      const uuid = this.generateUuid()
      this.currentUuid = uuid
      navigator.clipboard.writeText(uuid).then(() => {
        this.$message.success('UUID 已复制: ' + uuid)
      })
    },
    goToJson() {
      this.$router.push('/format/json')
    },
    goToBase64() {
      this.$router.push('/encode/base64')
    },
    toolColor(index) {
      const c = this.toolColorPalette[index % this.toolColorPalette.length]
      return {
        '--tbg': c.bg,
        '--tbd': c.border,
        '--ttx': c.text
      }
    }
  }
}
</script>

