<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Markdown 格式化</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="loadExample">加载示例</el-button>
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span>输入</span>
            </div>
            <el-input
              v-model="input"
              type="textarea"
              :rows="22"
              placeholder="输入 Markdown..."
            />
          </div>
        </el-col>

        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span>{{ previewMode ? '预览' : '格式化输出' }}</span>
              <div>
                <el-button type="text" size="mini" @click="previewMode = !previewMode">
                  {{ previewMode ? '查看源码' : '查看预览' }}
                </el-button>
                <el-button type="text" size="mini" @click="copyOutput">复制</el-button>
                <el-button type="text" size="mini" @click="downloadOutput">下载</el-button>
              </div>
            </div>
            <div
              v-show="previewMode"
              class="markdown-preview"
              v-html="renderedHtml"
            />
            <el-input
              v-show="!previewMode"
              v-model="output"
              type="textarea"
              :rows="22"
              readonly
              placeholder="格式化后的 Markdown 将显示在这里..."
            />
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-form :inline="true" size="small">
            <el-form-item label="无序列表符号">
              <el-select v-model="bulletMarker" style="width: 90px">
                <el-option label="-" value="-" />
                <el-option label="*" value="*" />
                <el-option label="+" value="+" />
              </el-select>
            </el-form-item>
            <el-form-item label="标题前空行">
              <el-switch v-model="blankBeforeHeading" />
            </el-form-item>
            <el-form-item label="清理多余空行">
              <el-switch v-model="collapseBlankLines" />
            </el-form-item>
            <el-form-item label="去除行尾空格">
              <el-switch v-model="trimTrailing" />
            </el-form-item>
            <el-form-item>
              <el-button type="primary" @click="format">格式化</el-button>
            </el-form-item>
          </el-form>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">
              <span>信息</span>
            </div>
            <el-descriptions :column="4" border size="small">
              <el-descriptions-item label="输入行数">{{ inputLines }}</el-descriptions-item>
              <el-descriptions-item label="输出行数">{{ outputLines }}</el-descriptions-item>
              <el-descriptions-item label="字符数">{{ output.length }}</el-descriptions-item>
              <el-descriptions-item label="单词数">{{ wordCount }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
import { marked } from 'marked'

export default {
  name: 'MarkdownTool',
  data() {
    return {
      input: '',
      output: '',
      previewMode: false,
      bulletMarker: '-',
      blankBeforeHeading: true,
      collapseBlankLines: true,
      trimTrailing: true
    }
  },
  computed: {
    inputLines() {
      return this.input ? this.input.split('\n').length : 0
    },
    outputLines() {
      return this.output ? this.output.split('\n').length : 0
    },
    wordCount() {
      const text = this.output.trim()
      if (!text) return 0
      const matches = text.match(/[一-龥]|[A-Za-z0-9]+/g)
      return matches ? matches.length : 0
    },
    renderedHtml() {
      const source = this.output || this.input
      if (!source) return ''
      try {
        return marked.parse(source, { breaks: true, gfm: true })
      } catch (e) {
        return '<p style="color:#f56c6c">预览失败: ' + e.message + '</p>'
      }
    }
  },
  methods: {
    format() {
      if (!this.input.trim()) {
        this.$message.warning('请输入 Markdown')
        return
      }
      try {
        this.output = this.formatMarkdown(this.input)
        this.$message.success('格式化成功')
      } catch (error) {
        this.$message.error('格式化失败: ' + error.message)
      }
    },
    formatMarkdown(src) {
      let lines = src.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n')
      const out = []
      let inFence = false
      let fenceToken = ''

      const headingRe = /^(#{1,6})\s*(\S.*?)\s*#*\s*$/
      const orderedRe = /^(\s*)(\d+)([.)])\s+(.*)$/
      const bulletRe = /^(\s*)([-*+])\s+(.*)$/

      for (let i = 0; i < lines.length; i++) {
        let line = lines[i]

        // 处理代码围栏，围栏内部不做任何改动
        const fenceMatch = line.match(/^(\s*)(```|~~~)(.*)$/)
        if (fenceMatch) {
          const token = fenceMatch[2]
          if (!inFence) {
            inFence = true
            fenceToken = token
          } else if (token === fenceToken) {
            inFence = false
            fenceToken = ''
          }
          out.push(line)
          continue
        }
        if (inFence) {
          out.push(line)
          continue
        }

        if (this.trimTrailing) {
          line = line.replace(/[ \t]+$/, '')
        }

        // 标题规范化：# 后保证一个空格，去掉行尾的 #
        const h = line.match(headingRe)
        if (h) {
          const normalized = h[1] + ' ' + h[2].trim()
          if (this.blankBeforeHeading && out.length > 0 && out[out.length - 1].trim() !== '') {
            out.push('')
          }
          out.push(normalized)
          // 标题后保证一个空行
          if (i + 1 < lines.length && lines[i + 1].trim() !== '') {
            out.push('')
          }
          continue
        }

        // 无序列表符号统一
        const b = line.match(bulletRe)
        if (b) {
          out.push(b[1] + this.bulletMarker + ' ' + b[3])
          continue
        }

        // 有序列表点号统一为 .
        const o = line.match(orderedRe)
        if (o) {
          out.push(o[1] + o[2] + '. ' + o[4])
          continue
        }

        out.push(line)
      }

      let result = out.join('\n')

      // 合并多余空行（最多保留一个空行）
      if (this.collapseBlankLines) {
        result = result.replace(/\n{3,}/g, '\n\n')
      }

      // 去除首尾多余空行，结尾保留一个换行
      result = result.replace(/^\n+/, '').replace(/\n+$/, '') + '\n'

      return result
    },
    copyOutput() {
      if (!this.output) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.output).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadOutput() {
      if (!this.output) {
        this.$message.warning('没有可下载的内容')
        return
      }
      const blob = new Blob([this.output], { type: 'text/markdown;charset=utf-8;' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'formatted.md'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    loadExample() {
      this.input = `#    标题一   ###
这是一段文本。



##二级标题没有空格
*   列表项一
+ 列表项二
-    列表项三

1) 有序项一
2) 有序项二

\`\`\`js
const a = 1;
console.log(a);
\`\`\`

普通段落，行尾有空格   `
      this.format()
    },
    clearAll() {
      this.input = ''
      this.output = ''
    }
  }
}
</script>

