<template>
  <div class="json-path-tool">
    <el-card>
      <div slot="header">
        <span>JSONPath 查询工具</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <div class="section-header">
            <span>JSON 数据</span>
            <el-button type="text" @click="formatJson">格式化</el-button>
          </div>
          <el-input
            v-model="jsonInput"
            type="textarea"
            :rows="15"
            placeholder="输入 JSON 数据..."
          />
        </el-col>

        <el-col :span="12">
          <div class="section-header">
            <span>JSONPath 表达式</span>
          </div>
          <el-input
            v-model="jsonPath"
            placeholder="输入 JSONPath 表达式，如 $.store.book[*].author"
            style="margin-bottom: 10px"
          >
            <el-button slot="append" type="primary" @click="executeQuery">执行</el-button>
          </el-input>

          <el-divider>常用表达式</el-divider>
          <div class="quick-paths">
            <el-tag v-for="path in quickPaths" :key="path" @click="jsonPath = path" style="cursor: pointer; margin: 3px">
              {{ path }}
            </el-tag>
          </div>

          <el-divider>查询结果</el-divider>
          <el-input
            v-model="queryResult"
            type="textarea"
            :rows="10"
            readonly
            placeholder="查询结果..."
          />
          <div style="margin-top: 10px">
            <el-button type="primary" @click="copyResult">复制结果</el-button>
            <el-button @click="clear">清空</el-button>
          </div>
        </el-col>
      </el-row>

      <el-divider>JSONPath 语法参考</el-divider>

      <el-table :data="syntaxReference" border size="small">
        <el-table-column prop="syntax" label="语法" width="150" />
        <el-table-column prop="description" label="描述" />
        <el-table-column prop="example" label="示例" width="200" />
      </el-table>

      <el-divider>示例数据</el-divider>

      <el-button @click="loadExample('store')">书店示例</el-button>
      <el-button @click="loadExample('users')">用户列表</el-button>
      <el-button @click="loadExample('nested')">嵌套对象</el-button>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'JsonPathTool',
  data() {
    return {
      jsonInput: '',
      jsonPath: '$',
      queryResult: '',
      quickPaths: [
        '$',
        '$.*',
        '$..*',
        '$[0]',
        '$[-1:]',
        '$[0:2]',
        '$[*]',
        '$..author',
        '$.store.book[*].author',
        '$..book[?(@.price < 10)]'
      ],
      syntaxReference: [
        { syntax: '$', description: '根对象', example: '$' },
        { syntax: '.', description: '子节点', example: '$.store' },
        { syntax: '..', description: '递归下降', example: '$..author' },
        { syntax: '*', description: '通配符', example: '$.store.*' },
        { syntax: '[]', description: '数组索引', example: '$[0], $[0:2]' },
        { syntax: '[*]', description: '数组所有元素', example: '$.store.book[*]' },
        { syntax: '[-1:]', description: '最后一个元素', example: '$[-1:]' },
        { syntax: '[?()]', description: '过滤表达式', example: '$[?(@.price < 10)]' },
        { syntax: '(@)', description: '当前节点', example: '$[?(@.price < 10)]' }
      ]
    }
  },
  methods: {
    executeQuery() {
      if (!this.jsonInput) {
        this.$message.warning('请输入 JSON 数据')
        return
      }

      try {
        const json = JSON.parse(this.jsonInput)
        const result = this.jsonPathQuery(json, this.jsonPath)
        this.queryResult = JSON.stringify(result, null, 2)
        this.$message.success('查询成功')
      } catch (e) {
        this.$message.error('查询失败: ' + e.message)
      }
    },
    jsonPathQuery(obj, path) {
      if (!path || path === '$') return obj

      const tokens = this.tokenize(path)
      let result = [obj]

      for (const token of tokens) {
        const newResult = []
        for (const current of result) {
          if (current === null || current === undefined) continue
          
          if (token.type === 'child') {
            if (Array.isArray(current)) {
              if (token.value === '*') {
                newResult.push(...current)
              } else if (typeof token.value === 'number') {
                if (current[token.value] !== undefined) {
                  newResult.push(current[token.value])
                }
              } else if (token.value === 'length') {
                newResult.push(current.length)
              }
            } else if (typeof current === 'object') {
              if (token.value === '*') {
                newResult.push(...Object.values(current))
              } else if (current[token.value] !== undefined) {
                newResult.push(current[token.value])
              }
            }
          } else if (token.type === 'descendant') {
            this.findDescendants(current, token.value, newResult)
          } else if (token.type === 'slice') {
            if (Array.isArray(current)) {
              const sliced = current.slice(token.start, token.end)
              newResult.push(...sliced)
            }
          } else if (token.type === 'filter') {
            if (Array.isArray(current)) {
              for (const item of current) {
                if (this.evaluateFilter(item, token.expression)) {
                  newResult.push(item)
                }
              }
            }
          } else if (token.type === 'all') {
            if (Array.isArray(current)) {
              newResult.push(...current)
            } else if (typeof current === 'object') {
              newResult.push(...Object.values(current))
            }
          }
        }
        result = newResult
      }

      return result.length === 1 ? result[0] : result
    },
    tokenize(path) {
      const tokens = []
      let i = 1

      while (i < path.length) {
        if (path[i] === '.') {
          if (path[i + 1] === '.') {
            i += 2
            let name = ''
            while (i < path.length && path[i] !== '.' && path[i] !== '[') {
              name += path[i]
              i++
            }
            tokens.push({ type: 'descendant', value: name })
          } else {
            i++
            if (path[i] === '*') {
              tokens.push({ type: 'all' })
              i++
            } else {
              let name = ''
              while (i < path.length && path[i] !== '.' && path[i] !== '[') {
                name += path[i]
                i++
              }
              tokens.push({ type: 'child', value: name })
            }
          }
        } else if (path[i] === '[') {
          i++
          if (path[i] === '*') {
            tokens.push({ type: 'all' })
            i += 2
          } else if (path[i] === '?') {
            i += 2
            let expr = ''
            let parenCount = 1
            while (i < path.length && parenCount > 0) {
              if (path[i] === '(') parenCount++
              if (path[i] === ')') parenCount--
              if (parenCount > 0) expr += path[i]
              i++
            }
            tokens.push({ type: 'filter', expression: expr })
            i++
          } else if (path[i] === "'") {
            i++
            let name = ''
            while (i < path.length && path[i] !== "'") {
              name += path[i]
              i++
            }
            i += 2
            tokens.push({ type: 'child', value: name })
          } else {
            let num = ''
            if (path[i] === '-') {
              num += path[i]
              i++
            }
            while (i < path.length && /\d/.test(path[i])) {
              num += path[i]
              i++
            }
            if (path[i] === ':') {
              i++
              let end = ''
              while (i < path.length && /\d/.test(path[i])) {
                end += path[i]
                i++
              }
              tokens.push({ type: 'slice', start: parseInt(num) || 0, end: parseInt(end) || undefined })
              i++
            } else {
              tokens.push({ type: 'child', value: parseInt(num) })
              i++
            }
          }
        } else {
          i++
        }
      }

      return tokens
    },
    findDescendants(obj, name, result) {
      if (Array.isArray(obj)) {
        for (const item of obj) {
          this.findDescendants(item, name, result)
        }
      } else if (typeof obj === 'object' && obj !== null) {
        for (const [key, value] of Object.entries(obj)) {
          if (key === name || name === '*') {
            result.push(value)
          }
          this.findDescendants(value, name, result)
        }
      }
    },
    evaluateFilter(obj, expression) {
      const match = expression.match(/@\.(\w+)\s*([<>=!]+)\s*(.+)/)
      if (!match) return false
      
      const [, field, operator, value] = match
      const fieldValue = obj[field]
      const compareValue = value.trim().replace(/^['"]|['"]$/g, '')
      
      if (!isNaN(compareValue)) {
        const num = parseFloat(compareValue)
        switch (operator) {
          case '<': return fieldValue < num
          case '<=': return fieldValue <= num
          case '>': return fieldValue > num
          case '>=': return fieldValue >= num
          case '==': return fieldValue == num
          case '!=': return fieldValue != num
        }
      }
      
      switch (operator) {
        case '==': return fieldValue == compareValue
        case '!=': return fieldValue != compareValue
      }
      
      return false
    },
    formatJson() {
      try {
        const json = JSON.parse(this.jsonInput)
        this.jsonInput = JSON.stringify(json, null, 2)
        this.$message.success('格式化成功')
      } catch (e) {
        this.$message.error('JSON 格式错误')
      }
    },
    copyResult() {
      if (!this.queryResult) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.queryResult).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    clear() {
      this.jsonInput = ''
      this.jsonPath = '$'
      this.queryResult = ''
    },
    loadExample(type) {
      const examples = {
        store: {
          store: {
            book: [
              { category: 'reference', author: 'Nigel Rees', title: 'Sayings of the Century', price: 8.95 },
              { category: 'fiction', author: 'Evelyn Waugh', title: 'Sword of Honour', price: 12.99 },
              { category: 'fiction', author: 'Herman Melville', title: 'Moby Dick', isbn: '0-553-21311-3', price: 8.99 },
              { category: 'fiction', author: 'J. R. R. Tolkien', title: 'The Lord of the Rings', isbn: '0-395-19395-8', price: 22.99 }
            ],
            bicycle: { color: 'red', price: 19.95 }
          },
          expensive: 10
        },
        users: [
          { id: 1, name: 'Alice', age: 25, email: 'alice@example.com' },
          { id: 2, name: 'Bob', age: 30, email: 'bob@example.com' },
          { id: 3, name: 'Charlie', age: 35, email: 'charlie@example.com' }
        ],
        nested: {
          level1: {
            level2: {
              level3: {
                value: 'deep value',
                items: [1, 2, 3]
              }
            }
          }
        }
      }
      this.jsonInput = JSON.stringify(examples[type], null, 2)
    }
  }
}
</script>

<style scoped>
.json-path-tool {
  padding: 20px;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.quick-paths {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}
</style>
