        const apis = [
          // API 1: exchangerate-api.com (免费，无需 key)
          {
            url: 'https://api.exchangerate-api.com/v4/latest/USD',
            parser: (data) => data.rates
          },
          // API 2: 使用 CORS 代理
          {
            url: 'https://api.allorigins.win/raw?url=https://api.exchangerate-api.com/v4/latest/USD',
            parser: (data) => data.rates
          },
