        const fromToUsd = 1 / (this.rates[from] || 1)
        const usdToTo = this.rates[to] || 1
        return fromToUsd * usdToTo
      }
    },
    
    convertCurrency() {
      const { input, from, to } = this.currency
      const rate = this.getExchangeRate(from, to)
      const result = input * rate
      this.currency.result = result.toFixed(2)
    },
    
    clearAll() {
      this.currency = {
        input: 1,
        from: 'USD',
        to: 'CNY',
        result: ''
      }
      this.convertCurrency()
    }
  }
}
</script>

