<template>
  <div class="data-export-clean-tool">
    <el-card>
      <div slot="header">
        <span>数据导出与清洗</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
          <el-button size="small" @click="loadExample" type="primary">加载示例</el-button>
        </el-button-group>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-card shadow="hover">
            <div slot="header">
              <span>数据输入</span>
              <el-button size="small" @click="importData" type="info">导入</el-button>
            </div>
            <el-tabs v-model="activeTab">
              <el-tab-pane label="JSON 数据">
                <el-input
                  type="textarea"
                  :rows="15"
                  v-model="jsonData"
                  placeholder="输入 JSON 格式的数据..."
                  @change="parseData"
                />
              </el-tab-pane>
              <el-tab-pane label="CSV 数据">
                <el-input
                  type="textarea"
                  :rows="15"
                  v-model="csvData"
                  placeholder="输入 CSV 格式的数据..."
                  @change="parseData"
                />
              </el-tab-pane>
            </el-tabs>
          </el-card>

          <el-card shadow="hover" style="margin-top: 20px">
            <div slot="header">
              <span>数据清洗</span>
            </div>
            <el-form :model="cleanConfig" label-width="120px">
              <el-form-item label="去除空白">
                <el-switch v-model="cleanConfig.trimWhitespace" @change="cleanData" />
              </el-form-item>
              <el-form-item label="去除重复行">
                <el-switch v-model="cleanConfig.removeDuplicates" @change="cleanData" />
              </el-form-item>
              <el-form-item label="去除空值">
                <el-switch v-model="cleanConfig.removeNulls" @change="cleanData" />
              </el-form-item>
              <el-form-item label="格式化 JSON">
                <el-switch v-model="cleanConfig.formatJson" @change="cleanData" />
              </el-form-item>
              <el-form-item label="排序字段">
                <el-select v-model="cleanConfig.sortField" @change="cleanData" style="width: 100%">
                  <el-option label="无排序" value="" />
                  <el-option
                    v-for="field in fields"
                    :key="field"
                    :label="field"
                    :value="field"
                  />
                </el-select>
              </el-form-item>
              <el-form-item label="排序方式">
                <el-radio-group v-model="cleanConfig.sortOrder" @change="cleanData">
                  <el-radio-button label="asc">升序</el-radio-button>
                  <el-radio-button label="desc">降序</el-radio-button>
                </el-radio-group>
              </el-form-item>
            </el-form>
          </el-card>
        </el-col>

        <el-col :span="12">
          <el-card shadow="hover">
            <div slot="header">
              <span>数据预览</span>
            </div>
            <el-table
              :data="cleanedData.slice(0, 10)"
              border
              style="width: 100%"
              size="small"
            >
              <el-table-column
                v-for="field in fields"
                :key="field"
                :prop="field"
                :label="field"
                min-width="100"
              />
            </el-table>
            <div v-if="cleanedData.length > 10" style="text-align: center; margin-top: 10px; color: #909399">
              仅显示前 10 条数据
            </div>
          </el-card>

          <el-card shadow="hover" style="margin-top: 20px">
            <div slot="header">
              <span>数据导出</span>
            </div>
            <el-form :model="exportConfig" label-width="100px">
              <el-form-item label="导出格式">
                <el-select v-model="exportConfig.format" style="width: 100%">
                  <el-option label="JSON" value="json" />
                  <el-option label="CSV" value="csv" />
                  <el-option label="TXT" value="txt" />
                  <el-option label="Excel" value="excel" />
                </el-select>
              </el-form-item>
              <el-form-item label="文件名">
                <el-input v-model="exportConfig.filename" placeholder="输入文件名" />
              </el-form-item>
              <el-form-item label="导出选项">
                <el-checkbox v-model="exportConfig.includeHeaders">包含表头</el-checkbox>
              </el-form-item>
              <el-form-item>
                <el-button type="primary" @click="exportData" style="width: 100%">
                  <i class="el-icon-download"></i> 导出数据
                </el-button>
              </el-form-item>
            </el-form>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'DataExportCleanTool',
  data() {
    return {
      activeTab: 'JSON 数据',
      jsonData: '',
      csvData: '',
      parsedData: [],
      cleanedData: [],
      fields: [],
      cleanConfig: {
        trimWhitespace: true,
        removeDuplicates: false,
        removeNulls: false,
        formatJson: true,
        sortField: '',
        sortOrder: 'asc'
      },
      exportConfig: {
        format: 'json',
        filename: 'data',
        includeHeaders: true
      }
    }
  },
  methods: {
    clearAll() {
      this.jsonData = ''
      this.csvData = ''
      this.parsedData = []
      this.cleanedData = []
      this.fields = []
      this.cleanConfig = {
        trimWhitespace: true,
        removeDuplicates: false,
        removeNulls: false,
        formatJson: true,
        sortField: '',
        sortOrder: 'asc'
      }
      this.exportConfig = {
        format: 'json',
        filename: 'data',
        includeHeaders: true
      }
    },
    loadExample() {
      this.jsonData = JSON.stringify([
        {
          "name": "  John Doe  ",
          "email": "john@example.com",
          "age": 30,
          "active": true,
          "created_at": "2023-01-01"
        },
        {
          "name": "Jane Smith",
          "email": "jane@example.com",
          "age": 25,
          "active": true,
          "created_at": "2023-01-02"
        },
        {
          "name": "  Bob Johnson  ",
          "email": "bob@example.com",
          "age": null,
          "active": false,
          "created_at": "2023-01-03"
        },
        {
          "name": "John Doe",
          "email": "john@example.com",
          "age": 30,
          "active": true,
          "created_at": "2023-01-01"
        }
      ], null, 2)
      this.activeTab = 'JSON 数据'
      this.parseData()
    },
    parseData() {
      try {
        if (this.activeTab === 'JSON 数据') {
          const data = JSON.parse(this.jsonData)
          if (Array.isArray(data)) {
            this.parsedData = data
            if (data.length > 0) {
              this.fields = Object.keys(data[0])
            }
          } else {
            this.$message.error('JSON 数据必须是数组格式')
          }
        } else if (this.activeTab === 'CSV 数据') {
          const lines = this.csvData.split(/\r?\n/).filter(line => line.trim())
          if (lines.length < 2) {
            this.$message.error('CSV 数据至少需要包含表头和一行数据')
            return
          }
          
          const headers = this.parseCsvLine(lines[0])
          this.fields = headers
          
          const data = []
          for (let i = 1; i < lines.length; i++) {
            const values = this.parseCsvLine(lines[i])
            const row = {}
            headers.forEach((header, index) => {
              row[header] = values[index] || ''
            })
            data.push(row)
          }
          
          this.parsedData = data
        }
        this.cleanData()
      } catch (error) {
        this.$message.error('数据格式错误')
      }
    },
    parseCsvLine(line) {
      const result = []
      let current = ''
      let inQuotes = false
      
      for (let i = 0; i < line.length; i++) {
        const char = line[i]
        if (char === '"') {
          inQuotes = !inQuotes
        } else if (char === ',' && !inQuotes) {
          result.push(current)
          current = ''
        } else {
          current += char
        }
      }
      result.push(current)
      return result
    },
    cleanData() {
      let data = JSON.parse(JSON.stringify(this.parsedData))
      
      // 去除空白
      if (this.cleanConfig.trimWhitespace) {
        data = data.map(row => {
          const cleanedRow = {}
          Object.keys(row).forEach(key => {
            if (typeof row[key] === 'string') {
              cleanedRow[key] = row[key].trim()
            } else {
              cleanedRow[key] = row[key]
            }
          })
          return cleanedRow
        })
      }
      
      // 去除重复行
      if (this.cleanConfig.removeDuplicates) {
        const seen = new Set()
        data = data.filter(row => {
          const key = JSON.stringify(row)
          if (seen.has(key)) {
            return false
          }
          seen.add(key)
          return true
        })
      }
      
      // 去除空值
      if (this.cleanConfig.removeNulls) {
        data = data.map(row => {
          const cleanedRow = {}
          Object.keys(row).forEach(key => {
            if (row[key] !== null && row[key] !== undefined && row[key] !== '') {
              cleanedRow[key] = row[key]
            }
          })
          return cleanedRow
        })
      }
      
      // 排序
      if (this.cleanConfig.sortField) {
        data.sort((a, b) => {
          const aValue = a[this.cleanConfig.sortField]
          const bValue = b[this.cleanConfig.sortField]
          
          if (aValue < bValue) {
            return this.cleanConfig.sortOrder === 'asc' ? -1 : 1
          }
          if (aValue > bValue) {
            return this.cleanConfig.sortOrder === 'asc' ? 1 : -1
          }
          return 0
        })
      }
      
      this.cleanedData = data
    },
    exportData() {
      if (this.cleanedData.length === 0) {
        this.$message.error('没有数据可导出')
        return
      }
      
      let content = ''
      let filename = this.exportConfig.filename || 'data'
      
      switch (this.exportConfig.format) {
        case 'json':
          content = JSON.stringify(this.cleanedData, null, 2)
          filename += '.json'
          break
        case 'csv':
          content = this.generateCsv()
          filename += '.csv'
          break
        case 'txt':
          content = this.generateTxt()
          filename += '.txt'
          break
        case 'excel':
          this.exportExcel()
          return
      }
      
      this.downloadFile(content, filename)
    },
    generateCsv() {
      if (this.cleanedData.length === 0) return ''
      
      const headers = this.fields
      let csv = ''
      
      if (this.exportConfig.includeHeaders) {
        csv += headers.join(',') + '\n'
      }
      
      this.cleanedData.forEach(row => {
        const values = headers.map(header => {
          const value = row[header] || ''
          if (typeof value === 'string' && (value.includes(',') || value.includes('"') || value.includes('\n'))) {
            return `"${value.replace(/"/g, '""')}"`
          }
          return value
        })
        csv += values.join(',') + '\n'
      })
      
      return csv
    },
    generateTxt() {
      if (this.cleanedData.length === 0) return ''
      
      let txt = ''
      this.cleanedData.forEach((row, index) => {
        txt += `=== 记录 ${index + 1} ===\n`
        Object.keys(row).forEach(key => {
          txt += `${key}: ${row[key]}\n`
        })
        txt += '\n'
      })
      
      return txt
    },
    exportExcel() {
      // 模拟 Excel 导出（实际项目中可以使用 xlsx 库）
      this.$message.info('Excel 导出功能需要 xlsx 库，当前使用 CSV 格式代替')
      const content = this.generateCsv()
      this.downloadFile(content, `${this.exportConfig.filename || 'data'}.csv`)
    },
    downloadFile(content, filename) {
      const blob = new Blob([content], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = filename
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
    },
    importData() {
      const input = document.createElement('input')
      input.type = 'file'
      input.accept = '.json,.csv,.txt'
      input.onchange = (e) => {
        const file = e.target.files[0]
        if (file) {
          const reader = new FileReader()
          reader.onload = (e) => {
            if (file.name.endsWith('.json')) {
              this.jsonData = e.target.result
              this.activeTab = 'JSON 数据'
            } else if (file.name.endsWith('.csv')) {
              this.csvData = e.target.result
              this.activeTab = 'CSV 数据'
            }
            this.parseData()
          }
          reader.readAsText(file)
        }
      }
      input.click()
    }
  }
}
</script>

<style lang="scss" scoped>
.data-export-clean-tool {
  .header-actions {
    float: right;
  }
}
</style>