<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>URL 解析器</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="24">
          <div class="input-section">
            <div class="section-header">
              <span>URL</span>
              <el-button type="text" size="mini" @click="loadExample">加载示例</el-button>
            </div>
            <el-input
              v-model="url"
              placeholder="输入 URL..."
              @input="parseUrl"
            >
              <el-button slot="append" @click="parseUrl">解析</el-button>
            </el-input>
          </div>
        </el-col>
      </el-row>
      
      <el-divider>解析结果</el-divider>
      
      <el-row :gutter="20">
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">
              <span>URL 组成部分</span>
            </div>
            <el-descriptions :column="1" border size="small">
              <el-descriptions-item label="协议">
                <el-button type="text" size="mini" @click="copy('protocol')">复制</el-button>
                {{ parsed.protocol || '-' }}
              </el-descriptions-item>
              <el-descriptions-item label="主机">
                <el-button type="text" size="mini" @click="copy('hostname')">复制</el-button>
                {{ parsed.hostname || '-' }}
              </el-descriptions-item>
              <el-descriptions-item label="端口">
                <el-button type="text" size="mini" @click="copy('port')">复制</el-button>
                {{ parsed.port || '-' }}
              </el-descriptions-item>
              <el-descriptions-item label="路径">
                <el-button type="text" size="mini" @click="copy('pathname')">复制</el-button>
                {{ parsed.pathname || '-' }}
              </el-descriptions-item>
              <el-descriptions-item label="查询参数">
                <el-button type="text" size="mini" @click="copy('search')">复制</el-button>
                {{ parsed.search || '-' }}
              </el-descriptions-item>
              <el-descriptions-item label="哈希">
                <el-button type="text" size="mini" @click="copy('hash')">复制</el-button>
                {{ parsed.hash || '-' }}
              </el-descriptions-item>
              <el-descriptions-item label="用户名">
                <el-button type="text" size="mini" @click="copy('username')">复制</el-button>
                {{ parsed.username || '-' }}
              </el-descriptions-item>
              <el-descriptions-item label="密码">
                <el-button type="text" size="mini" @click="copy('password')">复制</el-button>
                {{ parsed.password ? '***' : '-' }}
              </el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
        
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">
              <span>查询参数</span>
            </div>
            <el-table
              :data="queryParams"
              border
              stripe
              max-height="300"
              style="width: 100%"
            >
              <el-table-column prop="key" label="参数名" width="150" />
              <el-table-column prop="value" label="参数值">
                <template slot-scope="scope">
                  <el-button type="text" size="mini" @click="copyParam(scope.row.value)">复制</el-button>
                  {{ scope.row.value }}
                </template>
              </el-table-column>
            </el-table>
          </el-card>
        </el-col>
      </el-row>
      
      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">
              <span>编码/解码</span>
            </div>
            <el-row :gutter="20">
              <el-col :span="12">
                <div class="section-header">
                  <span>URL 编码</span>
                </div>
                <el-input
                  v-model="encodedUrl"
                  type="textarea"
                  :rows="3"
                  readonly
                />
                <el-button type="text" size="small" @click="copyEncoded">复制</el-button>
              </el-col>
              <el-col :span="12">
                <div class="section-header">
                  <span>URL 解码</span>
                </div>
                <el-input
                  v-model="decodedUrl"
                  type="textarea"
                  :rows="3"
                  readonly
                />
                <el-button type="text" size="small" @click="copyDecoded">复制</el-button>
              </el-col>
            </el-row>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'UrlParserTool',
  data() {
    return {
      url: '',
      parsed: {},
      queryParams: [],
      encodedUrl: '',
      decodedUrl: ''
    }
  },
  methods: {
    parseUrl() {
      if (!this.url) {
        this.parsed = {}
        this.queryParams = []
        this.encodedUrl = ''
        this.decodedUrl = ''
        return
      }
      
      try {
        const parsed = new URL(this.url)
        
        this.parsed = {
          protocol: parsed.protocol,
          hostname: parsed.hostname,
          port: parsed.port,
          pathname: parsed.pathname,
          search: parsed.search,
          hash: parsed.hash,
          username: parsed.username,
          password: parsed.password
        }
        
        this.queryParams = []
        parsed.searchParams.forEach((value, key) => {
          this.queryParams.push({ key, value })
        })
        
        this.encodedUrl = encodeURIComponent(this.url)
        this.decodedUrl = decodeURIComponent(this.url)
        
        this.$message.success('解析成功')
      } catch (error) {
        this.$message.error('解析失败: ' + error.message)
        this.parsed = {}
        this.queryParams = []
      }
    },
    copy(field) {
      const value = this.parsed[field]
      if (value) {
        navigator.clipboard.writeText(value).then(() => {
          this.$message.success('复制成功')
        }).catch(() => {
          this.$message.error('复制失败')
        })
      }
    },
    copyParam(value) {
      navigator.clipboard.writeText(value).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    copyEncoded() {
      navigator.clipboard.writeText(this.encodedUrl).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    copyDecoded() {
      navigator.clipboard.writeText(this.decodedUrl).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    loadExample() {
      this.url = 'https://user:pass@example.com:8080/path/to/page?name=张三&age=25&city=北京#section'
      this.parseUrl()
    },
    clearAll() {
      this.url = ''
      this.parsed = {}
      this.queryParams = []
      this.encodedUrl = ''
      this.decodedUrl = ''
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .tool-card {
    .header-actions {
      float: right;
    }
  }

  .input-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }
}
</style>
