<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>文本统计</span>
        <el-button size="small" @click="clearAll">清空</el-button>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="24">
          <div class="input-section">
            <div class="section-header">
              <span>输入文本</span>
              <el-tag size="mini" type="info">支持多行文本</el-tag>
            </div>
            <el-input
              v-model="textContent"
              type="textarea"
              :rows="10"
              placeholder="在此输入或粘贴文本进行统计分析..."
              @input="analyzeText"
            />
          </div>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px">
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">基本统计</div>
            <el-descriptions :column="2" border size="small">
              <el-descriptions-item label="字符数">{{ stats.chars }}</el-descriptions-item>
              <el-descriptions-item label="字符数(不含空格)">{{ stats.charsNoSpace }}</el-descriptions-item>
              <el-descriptions-item label="中文字符">{{ stats.chinese }}</el-descriptions-item>
              <el-descriptions-item label="英文字符">{{ stats.english }}</el-descriptions-item>
              <el-descriptions-item label="数字">{{ stats.numbers }}</el-descriptions-item>
              <el-descriptions-item label="标点符号">{{ stats.punctuation }}</el-descriptions-item>
              <el-descriptions-item label="单词数">{{ stats.words }}</el-descriptions-item>
              <el-descriptions-item label="行数">{{ stats.lines }}</el-descriptions-item>
              <el-descriptions-item label="段落数">{{ stats.paragraphs }}</el-descriptions-item>
              <el-descriptions-item label="句子数">{{ stats.sentences }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
        
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">阅读时间估算</div>
            <el-descriptions :column="1" border size="small">
              <el-descriptions-item label="中文阅读时间">{{ stats.readTimeChinese }} 分钟</el-descriptions-item>
              <el-descriptions-item label="英文阅读时间">{{ stats.readTimeEnglish }} 分钟</el-descriptions-item>
              <el-descriptions-item label="演讲时间">{{ stats.speakTime }} 分钟</el-descriptions-item>
              <el-descriptions-item label="A4纸页数">{{ stats.a4Pages }} 页</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px">
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">
              <span>字符频率 Top 20</span>
              <el-radio-group v-model="charFreqType" size="mini" style="float: right" @change="analyzeText">
                <el-radio-button label="all">全部</el-radio-button>
                <el-radio-button label="chinese">中文</el-radio-button>
                <el-radio-button label="english">英文</el-radio-button>
              </el-radio-group>
            </div>
            <el-table :data="charFrequency" border size="small" max-height="300">
              <el-table-column prop="char" label="字符" width="80" align="center">
                <template slot-scope="scope">
                  <span class="freq-char">{{ scope.row.char }}</span>
                </template>
              </el-table-column>
              <el-table-column prop="count" label="次数" width="80" />
              <el-table-column prop="percent" label="占比">
                <template slot-scope="scope">
                  <el-progress :percentage="scope.row.percent" :stroke-width="10" :show-text="false" />
                  <span class="percent-text">{{ scope.row.percent.toFixed(2) }}%</span>
                </template>
              </el-table-column>
            </el-table>
          </el-card>
        </el-col>
        
        <el-col :span="12">
          <el-card shadow="never">
            <div slot="header">词频统计 Top 20</div>
            <el-table :data="wordFrequency" border size="small" max-height="300">
              <el-table-column prop="word" label="词语" width="150">
                <template slot-scope="scope">
                  <span class="freq-word">{{ scope.row.word }}</span>
                </template>
              </el-table-column>
              <el-table-column prop="count" label="次数" width="80" />
              <el-table-column prop="percent" label="占比">
                <template slot-scope="scope">
                  <el-progress :percentage="scope.row.percent" :stroke-width="10" :show-text="false" />
                  <span class="percent-text">{{ scope.row.percent.toFixed(2) }}%</span>
                </template>
              </el-table-column>
            </el-table>
          </el-card>
        </el-col>
      </el-row>

      <el-row :gutter="20" style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">字符分布</div>
            <div class="char-distribution">
              <div class="dist-item">
                <span class="dist-label">中文字符</span>
                <el-progress :percentage="getPercentage(stats.chinese, stats.chars)" :stroke-width="20" />
              </div>
              <div class="dist-item">
                <span class="dist-label">英文字符</span>
                <el-progress :percentage="getPercentage(stats.english, stats.chars)" :stroke-width="20" color="#67C23A" />
              </div>
              <div class="dist-item">
                <span class="dist-label">数字</span>
                <el-progress :percentage="getPercentage(stats.numbers, stats.chars)" :stroke-width="20" color="#E6A23C" />
              </div>
              <div class="dist-item">
                <span class="dist-label">空格</span>
                <el-progress :percentage="getPercentage(stats.spaces, stats.chars)" :stroke-width="20" color="#909399" />
              </div>
              <div class="dist-item">
                <span class="dist-label">标点符号</span>
                <el-progress :percentage="getPercentage(stats.punctuation, stats.chars)" :stroke-width="20" color="#F56C6C" />
              </div>
            </div>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'TextStatsTool',
  data() {
    return {
      textContent: '',
      charFreqType: 'all',
      stats: {
        chars: 0,
        charsNoSpace: 0,
        chinese: 0,
        english: 0,
        numbers: 0,
        punctuation: 0,
        spaces: 0,
        words: 0,
        lines: 0,
        paragraphs: 0,
        sentences: 0,
        readTimeChinese: 0,
        readTimeEnglish: 0,
        speakTime: 0,
        a4Pages: 0
      },
      charFrequency: [],
      wordFrequency: []
    }
  },
  methods: {
    analyzeText() {
      const text = this.textContent
      
      // 基本统计
      this.stats.chars = text.length
      this.stats.charsNoSpace = text.replace(/\s/g, '').length
      this.stats.chinese = (text.match(/[\u4e00-\u9fa5]/g) || []).length
      this.stats.english = (text.match(/[a-zA-Z]/g) || []).length
      this.stats.numbers = (text.match(/[0-9]/g) || []).length
      this.stats.spaces = (text.match(/\s/g) || []).length
      this.stats.punctuation = (text.match(/[，。！？、；：""''（）【】《》,.!?;:'"()\[\]{}<>]/g) || []).length
      
      // 行和段落
      this.stats.lines = text ? text.split('\n').length : 0
      this.stats.paragraphs = text ? text.split(/\n\s*\n/).filter(p => p.trim()).length : 0
      
      // 句子数
      this.stats.sentences = (text.match(/[。！？.!?]+/g) || []).length
      
      // 单词数（英文单词 + 中文字符作为词）
      const englishWords = (text.match(/[a-zA-Z]+/g) || []).length
      this.stats.words = englishWords + this.stats.chinese
      
      // 阅读时间估算
      // 中文阅读速度约 300-500 字/分钟，取 400
      this.stats.readTimeChinese = Math.ceil(this.stats.chinese / 400)
      // 英文阅读速度约 200-250 词/分钟，取 225
      this.stats.readTimeEnglish = Math.ceil(englishWords / 225)
      // 演讲速度约 150-200 词/分钟，取 175
      this.stats.speakTime = Math.ceil(this.stats.words / 175)
      // A4纸约 500-800 字/页，取 600
      this.stats.a4Pages = Math.max(1, Math.ceil(this.stats.chars / 600))
      
      // 字符频率
      this.calculateCharFrequency(text)
      
      // 词频统计
      this.calculateWordFrequency(text)
    },
    calculateCharFrequency(text) {
      if (!text) {
        this.charFrequency = []
        return
      }
      
      let chars = text.replace(/\s/g, '')
      
      if (this.charFreqType === 'chinese') {
        chars = chars.match(/[\u4e00-\u9fa5]/g) || []
      } else if (this.charFreqType === 'english') {
        chars = chars.match(/[a-zA-Z]/g) || []
      } else {
        chars = chars.split('')
      }
      
      const freq = {}
      chars.forEach(char => {
        freq[char] = (freq[char] || 0) + 1
      })
      
      const total = chars.length || 1
      this.charFrequency = Object.entries(freq)
        .map(([char, count]) => ({
          char,
          count,
          percent: (count / total) * 100
        }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 20)
    },
    calculateWordFrequency(text) {
      if (!text) {
        this.wordFrequency = []
        return
      }
      
      // 提取英文单词和中文词语（简单按字分割）
      const englishWords = text.match(/[a-zA-Z]+/g) || []
      const chineseChars = text.match(/[\u4e00-\u9fa5]/g) || []
      
      const allWords = [
        ...englishWords.map(w => w.toLowerCase()),
        ...chineseChars
      ]
      
      const freq = {}
      allWords.forEach(word => {
        if (word.length > 0) {
          freq[word] = (freq[word] || 0) + 1
        }
      })
      
      const total = allWords.length || 1
      this.wordFrequency = Object.entries(freq)
        .map(([word, count]) => ({
          word,
          count,
          percent: (count / total) * 100
        }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 20)
    },
    getPercentage(value, total) {
      if (total === 0) return 0
      return Math.round((value / total) * 100)
    },
    clearAll() {
      this.textContent = ''
      this.stats = {
        chars: 0,
        charsNoSpace: 0,
        chinese: 0,
        english: 0,
        numbers: 0,
        punctuation: 0,
        spaces: 0,
        words: 0,
        lines: 0,
        paragraphs: 0,
        sentences: 0,
        readTimeChinese: 0,
        readTimeEnglish: 0,
        speakTime: 0,
        a4Pages: 0
      }
      this.charFrequency = []
      this.wordFrequency = []
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .input-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }

  .freq-char, .freq-word {
    font-weight: bold;
    color: #409EFF;
  }

  .percent-text {
    font-size: 12px;
    color: #606266;
    margin-left: 10px;
  }

  .char-distribution {
    .dist-item {
      display: flex;
      align-items: center;
      margin-bottom: 15px;

      .dist-label {
        width: 80px;
        font-weight: bold;
      }

      .el-progress {
        flex: 1;
      }
    }
  }
}
</style>
