<template>
  <div class="triangle-tool">
    <el-card>
      <div slot="header">
        <span>CSS 三角形生成器</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-form label-width="100px">
            <el-form-item label="方向">
              <el-select v-model="triangle.direction" style="width: 150px" @change="generateCSS">
                <el-option label="向上" value="up" />
                <el-option label="向下" value="down" />
                <el-option label="向左" value="left" />
                <el-option label="向右" value="right" />
                <el-option label="左上" value="top-left" />
                <el-option label="右上" value="top-right" />
                <el-option label="左下" value="bottom-left" />
                <el-option label="右下" value="bottom-right" />
              </el-select>
            </el-form-item>

            <el-form-item label="宽度">
              <el-slider v-model="triangle.width" :min="10" :max="200" @change="generateCSS" />
              <span>{{ triangle.width }}px</span>
            </el-form-item>

            <el-form-item label="高度">
              <el-slider v-model="triangle.height" :min="10" :max="200" @change="generateCSS" />
              <span>{{ triangle.height }}px</span>
            </el-form-item>

            <el-form-item label="颜色">
              <el-color-picker v-model="triangle.color" @change="generateCSS" />
              <el-input v-model="triangle.color" style="width: 120px; margin-left: 10px" @change="generateCSS" />
            </el-form-item>

            <el-form-item label="边框颜色">
              <el-color-picker v-model="triangle.borderColor" @change="generateCSS" />
              <el-input v-model="triangle.borderColor" style="width: 120px; margin-left: 10px" @change="generateCSS" />
            </el-form-item>

            <el-form-item label="边框宽度">
              <el-slider v-model="triangle.borderWidth" :min="0" :max="20" @change="generateCSS" />
              <span>{{ triangle.borderWidth }}px</span>
            </el-form-item>
          </el-form>

          <el-divider>预设样式</el-divider>
          <div class="preset-container">
            <div 
              v-for="(preset, index) in presets" 
              :key="index" 
              class="preset-item"
              @click="applyPreset(preset)"
            >
              <div class="preset-triangle" :style="getPresetStyle(preset)"></div>
              <span>{{ preset.name }}</span>
            </div>
          </div>
        </el-col>

        <el-col :span="12">
          <el-divider>预览</el-divider>
          <div class="preview-container">
            <div class="preview-triangle" :style="triangleStyle"></div>
          </div>

          <el-divider>生成的CSS代码</el-divider>
          <el-input
            type="textarea"
            :rows="12"
            :value="generatedCSS"
            readonly
          />
          <div style="margin-top: 10px">
            <el-button type="primary" @click="copyCSS">复制CSS</el-button>
            <el-button @click="reset">重置</el-button>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'TriangleTool',
  data() {
    return {
      triangle: {
        direction: 'up',
        width: 50,
        height: 50,
        color: '#409EFF',
        borderColor: '#ffffff',
        borderWidth: 0
      },
      presets: [
        { name: '蓝色向上', direction: 'up', width: 50, height: 50, color: '#409EFF' },
        { name: '绿色向下', direction: 'down', width: 50, height: 50, color: '#67C23A' },
        { name: '橙色向左', direction: 'left', width: 50, height: 50, color: '#E6A23C' },
        { name: '红色向右', direction: 'right', width: 50, height: 50, color: '#F56C6C' },
        { name: '紫色左上', direction: 'top-left', width: 50, height: 50, color: '#909399' },
        { name: '青色右上', direction: 'top-right', width: 50, height: 50, color: '#00d1b2' },
        { name: '粉色左下', direction: 'bottom-left', width: 50, height: 50, color: '#ff69b4' },
        { name: '棕色右下', direction: 'bottom-right', width: 50, height: 50, color: '#8b4513' }
      ]
    }
  },
  computed: {
    triangleStyle() {
      return this.getTriangleStyle(this.triangle)
    },
    generatedCSS() {
      return this.generateTriangleCSS(this.triangle)
    }
  },
  methods: {
    generateCSS() {
      // 触发计算属性更新
    },
    getTriangleStyle(config) {
      const { direction, width, height, color, borderColor, borderWidth } = config
      const halfWidth = width / 2
      const halfHeight = height / 2

      const styles = {
        width: '0',
        height: '0'
      }

      switch (direction) {
        case 'up':
          styles.borderLeft = `${halfWidth}px solid transparent`
          styles.borderRight = `${halfWidth}px solid transparent`
          styles.borderBottom = `${height}px solid ${color}`
          break
        case 'down':
          styles.borderLeft = `${halfWidth}px solid transparent`
          styles.borderRight = `${halfWidth}px solid transparent`
          styles.borderTop = `${height}px solid ${color}`
          break
        case 'left':
          styles.borderTop = `${halfHeight}px solid transparent`
          styles.borderBottom = `${halfHeight}px solid transparent`
          styles.borderRight = `${width}px solid ${color}`
          break
        case 'right':
          styles.borderTop = `${halfHeight}px solid transparent`
          styles.borderBottom = `${halfHeight}px solid transparent`
          styles.borderLeft = `${width}px solid ${color}`
          break
        case 'top-left':
          styles.borderTop = `${height}px solid ${color}`
          styles.borderRight = `${width}px solid transparent`
          break
        case 'top-right':
          styles.borderTop = `${height}px solid ${color}`
          styles.borderLeft = `${width}px solid transparent`
          break
        case 'bottom-left':
          styles.borderBottom = `${height}px solid ${color}`
          styles.borderRight = `${width}px solid transparent`
          break
        case 'bottom-right':
          styles.borderBottom = `${height}px solid ${color}`
          styles.borderLeft = `${width}px solid transparent`
          break
      }

      return styles
    },
    generateTriangleCSS(config) {
      const { direction, width, height, color } = config
      const halfWidth = width / 2
      const halfHeight = height / 2

      let css = `.triangle {\n  width: 0;\n  height: 0;\n`

      switch (direction) {
        case 'up':
          css += `  border-left: ${halfWidth}px solid transparent;\n`
          css += `  border-right: ${halfWidth}px solid transparent;\n`
          css += `  border-bottom: ${height}px solid ${color};\n`
          break
        case 'down':
          css += `  border-left: ${halfWidth}px solid transparent;\n`
          css += `  border-right: ${halfWidth}px solid transparent;\n`
          css += `  border-top: ${height}px solid ${color};\n`
          break
        case 'left':
          css += `  border-top: ${halfHeight}px solid transparent;\n`
          css += `  border-bottom: ${halfHeight}px solid transparent;\n`
          css += `  border-right: ${width}px solid ${color};\n`
          break
        case 'right':
          css += `  border-top: ${halfHeight}px solid transparent;\n`
          css += `  border-bottom: ${halfHeight}px solid transparent;\n`
          css += `  border-left: ${width}px solid ${color};\n`
          break
        case 'top-left':
          css += `  border-top: ${height}px solid ${color};\n`
          css += `  border-right: ${width}px solid transparent;\n`
          break
        case 'top-right':
          css += `  border-top: ${height}px solid ${color};\n`
          css += `  border-left: ${width}px solid transparent;\n`
          break
        case 'bottom-left':
          css += `  border-bottom: ${height}px solid ${color};\n`
          css += `  border-right: ${width}px solid transparent;\n`
          break
        case 'bottom-right':
          css += `  border-bottom: ${height}px solid ${color};\n`
          css += `  border-left: ${width}px solid transparent;\n`
          break
      }

      css += `}`

      return css
    },
    getPresetStyle(preset) {
      return this.getTriangleStyle(preset)
    },
    applyPreset(preset) {
      this.triangle = { ...this.triangle, ...preset }
    },
    copyCSS() {
      navigator.clipboard.writeText(this.generatedCSS).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    reset() {
      this.triangle = {
        direction: 'up',
        width: 50,
        height: 50,
        color: '#409EFF',
        borderColor: '#ffffff',
        borderWidth: 0
      }
    }
  }
}
</script>

<style scoped>
.triangle-tool {
  padding: 20px;
}

.preview-container {
  height: 200px;
  background: #f5f7fa;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.preview-triangle {
  transition: all 0.3s;
}

.preset-container {
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
}

.preset-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  padding: 10px;
  border-radius: 8px;
  transition: all 0.3s;
}

.preset-item:hover {
  background: #f5f7fa;
}

.preset-triangle {
  margin-bottom: 5px;
}

.preset-item span {
  font-size: 12px;
  color: #909399;
}
</style>
