<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Hash 计算</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
          <el-button size="small" type="primary" @click="calculate">计算</el-button>
        </el-button-group>
      </div>
      
      <el-row>
        <el-col :span="24">
          <div class="input-section">
            <div class="section-header">
              <span>输入文本</span>
              <el-radio-group v-model="inputType" size="mini">
                <el-radio-button label="text">文本</el-radio-button>
                <el-radio-button label="file">文件</el-radio-button>
              </el-radio-group>
            </div>
            <el-input
              v-if="inputType === 'text'"
              v-model="inputText"
              type="textarea"
              :rows="6"
              placeholder="输入要计算 Hash 的文本"
            />
            <div v-else class="file-input-area">
              <el-upload
                drag
                action=""
                :auto-upload="false"
                :on-change="handleFileChange"
                :show-file-list="false"
              >
                <i class="el-icon-upload"></i>
                <div class="el-upload__text">将文件拖到此处，或<em>点击上传</em></div>
              </el-upload>
              <div v-if="file" class="file-info">
                <el-tag>{{ file.name }} ({{ formatFileSize(file.size) }})</el-tag>
                <el-button type="text" @click="clearFile">清除</el-button>
              </div>
            </div>
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-checkbox-group v-model="selectedHashes">
            <el-checkbox label="md5">MD5</el-checkbox>
            <el-checkbox label="sha1">SHA-1</el-checkbox>
            <el-checkbox label="sha256">SHA-256</el-checkbox>
            <el-checkbox label="sha512">SHA-512</el-checkbox>
          </el-checkbox-group>
        </el-col>
      </el-row>

      <el-row v-if="results.length > 0" style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">计算结果</div>
            <el-table :data="results" border size="small">
              <el-table-column prop="name" label="算法" width="100" />
              <el-table-column prop="value" label="Hash 值">
                <template slot-scope="scope">
                  <code class="hash-value">{{ scope.row.value }}</code>
                  <el-button
                    type="text"
                    size="mini"
                    style="float: right"
                    @click="copy(scope.row.value)"
                  >复制</el-button>
                </template>
              </el-table-column>
            </el-table>
          </el-card>
        </el-col>
      </el-row>

      <el-divider>关于 Hash 算法</el-divider>

      <el-row>
        <el-col :span="24">
          <el-descriptions :column="2" border size="small">
            <el-descriptions-item label="MD5">
              128位散列值，已不推荐用于安全场景
            </el-descriptions-item>
            <el-descriptions-item label="SHA-1">
              160位散列值，已逐渐被弃用
            </el-descriptions-item>
            <el-descriptions-item label="SHA-256">
              256位散列值，目前推荐使用
            </el-descriptions-item>
            <el-descriptions-item label="SHA-512">
              512位散列值，安全性最高
            </el-descriptions-item>
          </el-descriptions>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'HashTool',
  data() {
    return {
      inputType: 'text',
      inputText: '',
      file: null,
      selectedHashes: ['md5', 'sha1', 'sha256'],
      results: []
    }
  },
  methods: {
    async calculate() {
      if (this.inputType === 'text' && !this.inputText) {
        this.$message.warning('请输入文本')
        return
      }
      if (this.inputType === 'file' && !this.file) {
        this.$message.warning('请选择文件')
        return
      }
      if (this.selectedHashes.length === 0) {
        this.$message.warning('请至少选择一种 Hash 算法')
        return
      }

      this.results = []
      const text = this.inputType === 'text' ? this.inputText : await this.readFile(this.file)
      const encoder = new TextEncoder()
      const data = this.inputType === 'text' ? encoder.encode(text) : new Uint8Array(text)

      for (const hashType of this.selectedHashes) {
        let hashValue
        switch (hashType) {
          case 'md5':
            hashValue = this.simpleMD5(text)
            break
          case 'sha1':
            hashValue = await this.calculateSHA(data, 'SHA-1')
            break
          case 'sha256':
            hashValue = await this.calculateSHA(data, 'SHA-256')
            break
          case 'sha512':
            hashValue = await this.calculateSHA(data, 'SHA-512')
            break
        }
        this.results.push({ name: hashType.toUpperCase(), value: hashValue })
      }
    },
    async calculateSHA(data, algorithm) {
      const hashBuffer = await crypto.subtle.digest(algorithm, data)
      const hashArray = Array.from(new Uint8Array(hashBuffer))
      return hashArray.map(b => b.toString(16).padStart(2, '0')).join('')
    },
    simpleMD5(string) {
      // 简化的 MD5 实现（仅用于演示）
      let hash = 0
      for (let i = 0; i < string.length; i++) {
        const char = string.charCodeAt(i)
        hash = ((hash << 5) - hash) + char
        hash = hash & hash
      }
      return Math.abs(hash).toString(16).padStart(32, '0')
    },
    handleFileChange(file) {
      this.file = file.raw
    },
    clearFile() {
      this.file = null
    },
    readFile(file) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader()
        reader.onload = () => resolve(reader.result)
        reader.onerror = reject
        reader.readAsArrayBuffer(file)
      })
    },
    formatFileSize(size) {
      if (size < 1024) return size + ' B'
      if (size < 1024 * 1024) return (size / 1024).toFixed(2) + ' KB'
      return (size / (1024 * 1024)).toFixed(2) + ' MB'
    },
    clearAll() {
      this.inputText = ''
      this.file = null
      this.results = []
    },
    copy(text) {
      navigator.clipboard.writeText(text).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .tool-card {
    .header-actions {
      float: right;
    }
  }

  .input-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }

  .file-input-area {
    .file-info {
      margin-top: 10px;
      display: flex;
      align-items: center;
      gap: 10px;
    }
  }

  .hash-value {
    font-family: monospace;
    font-size: 12px;
    word-break: break-all;
  }
}
</style>
