<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Base32/Base58 编解码</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>
      
      <el-tabs v-model="activeTab">
        <el-tab-pane label="Base32" name="base32">
          <div class="tab-content">
            <el-row :gutter="20">
              <el-col :span="12">
                <div class="input-section">
                  <div class="section-header">
                    <span>文本</span>
                    <el-button type="text" size="mini" @click="loadExample32">加载示例</el-button>
                  </div>
                  <el-input
                    v-model="base32.text"
                    type="textarea"
                    :rows="10"
                    placeholder="输入文本..."
                  />
                  <el-button type="primary" style="margin-top: 10px" @click="encodeBase32">
                    编码为 Base32
                  </el-button>
                </div>
              </el-col>
              
              <el-col :span="12">
                <div class="input-section">
                  <div class="section-header">
                    <span>Base32</span>
                    <div>
                      <el-button type="text" size="mini" @click="copyBase32">复制</el-button>
                      <el-button type="text" size="mini" @click="downloadBase32">下载</el-button>
                    </div>
                  </div>
                  <el-input
                    v-model="base32.encoded"
                    type="textarea"
                    :rows="10"
                    placeholder="输入 Base32..."
                  />
                  <el-button type="primary" style="margin-top: 10px" @click="decodeBase32">
                    解码为文本
                  </el-button>
                </div>
              </el-col>
            </el-row>
          </div>
        </el-tab-pane>
        
        <el-tab-pane label="Base58" name="base58">
          <div class="tab-content">
            <el-row :gutter="20">
              <el-col :span="12">
                <div class="input-section">
                  <div class="section-header">
                    <span>文本</span>
                    <el-button type="text" size="mini" @click="loadExample58">加载示例</el-button>
                  </div>
                  <el-input
                    v-model="base58.text"
                    type="textarea"
                    :rows="10"
                    placeholder="输入文本..."
                  />
                  <el-button type="primary" style="margin-top: 10px" @click="encodeBase58">
                    编码为 Base58
                  </el-button>
                </div>
              </el-col>
              
              <el-col :span="12">
                <div class="input-section">
                  <div class="section-header">
                    <span>Base58</span>
                    <div>
                      <el-button type="text" size="mini" @click="copyBase58">复制</el-button>
                      <el-button type="text" size="mini" @click="downloadBase58">下载</el-button>
                    </div>
                  </div>
                  <el-input
                    v-model="base58.encoded"
                    type="textarea"
                    :rows="10"
                    placeholder="输入 Base58..."
                  />
                  <el-button type="primary" style="margin-top: 10px" @click="decodeBase58">
                    解码为文本
                  </el-button>
                </div>
              </el-col>
            </el-row>
          </div>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'Base32Base58Tool',
  data() {
    return {
      activeTab: 'base32',
      base32: {
        text: '',
        encoded: ''
      },
      base58: {
        text: '',
        encoded: ''
      }
    }
  },
  methods: {
    encodeBase32() {
      if (!this.base32.text) {
        this.$message.warning('请输入文本')
        return
      }
      
      try {
        const encoder = new TextEncoder()
        const bytes = encoder.encode(this.base32.text)
        this.base32.encoded = this.base32Encode(bytes)
        this.$message.success('编码成功')
      } catch (error) {
        this.$message.error('编码失败: ' + error.message)
      }
    },
    decodeBase32() {
      if (!this.base32.encoded) {
        this.$message.warning('请输入 Base32')
        return
      }
      
      try {
        const bytes = this.base32Decode(this.base32.encoded)
        const decoder = new TextDecoder()
        this.base32.text = decoder.decode(bytes)
        this.$message.success('解码成功')
      } catch (error) {
        this.$message.error('解码失败: ' + error.message)
      }
    },
    base32Encode(bytes) {
      const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
      let result = ''
      let bits = 0
      let value = 0
      
      for (let i = 0; i < bytes.length; i++) {
        value = (value << 8) | bytes[i]
        bits += 8
        
        while (bits >= 5) {
          bits -= 5
          result += alphabet[(value >> bits) & 31]
        }
      }
      
      if (bits > 0) {
        result += alphabet[(value << (5 - bits)) & 31]
      }
      
      while (result.length % 8 !== 0) {
        result += '='
      }
      
      return result
    },
    base32Decode(str) {
      const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
      const lookup = {}
      
      for (let i = 0; i < alphabet.length; i++) {
        lookup[alphabet[i]] = i
      }
      
      str = str.replace(/=+$/, '')
      let result = []
      let bits = 0
      let value = 0
      
      for (let i = 0; i < str.length; i++) {
        value = (value << 5) | lookup[str[i]]
        bits += 5
        
        if (bits >= 8) {
          bits -= 8
          result.push((value >> bits) & 255)
        }
      }
      
      return new Uint8Array(result)
    },
    encodeBase58() {
      if (!this.base58.text) {
        this.$message.warning('请输入文本')
        return
      }
      
      try {
        const encoder = new TextEncoder()
        const bytes = encoder.encode(this.base58.text)
        this.base58.encoded = this.base58Encode(bytes)
        this.$message.success('编码成功')
      } catch (error) {
        this.$message.error('编码失败: ' + error.message)
      }
    },
    decodeBase58() {
      if (!this.base58.encoded) {
        this.$message.warning('请输入 Base58')
        return
      }
      
      try {
        const bytes = this.base58Decode(this.base58.encoded)
        const decoder = new TextDecoder()
        this.base58.text = decoder.decode(bytes)
        this.$message.success('解码成功')
      } catch (error) {
        this.$message.error('解码失败: ' + error.message)
      }
    },
    base58Encode(bytes) {
      const alphabet = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'
      let result = ''
      let num = 0n
      
      for (let i = 0; i < bytes.length; i++) {
        num = (num << 8n) | BigInt(bytes[i])
      }
      
      while (num > 0n) {
        const remainder = num % 58n
        result = alphabet[Number(remainder)] + result
        num = num / 58n
      }
      
      let leadingZeros = 0
      for (let i = 0; i < bytes.length && bytes[i] === 0; i++) {
        leadingZeros++
      }
      
      return alphabet[0].repeat(leadingZeros) + result
    },
    base58Decode(str) {
      const alphabet = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'
      const lookup = {}
      
      for (let i = 0; i < alphabet.length; i++) {
        lookup[alphabet[i]] = BigInt(i)
      }
      
      let num = 0n
      
      for (let i = 0; i < str.length; i++) {
        num = num * 58n + lookup[str[i]]
      }
      
      const bytes = []
      while (num > 0n) {
        bytes.unshift(Number(num & 255n))
        num = num >> 8n
      }
      
      let leadingZeros = 0
      for (let i = 0; i < str.length && str[i] === alphabet[0]; i++) {
        leadingZeros++
      }
      
      return new Uint8Array([...new Array(leadingZeros).fill(0), ...bytes])
    },
    copyBase32() {
      navigator.clipboard.writeText(this.base32.encoded).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadBase32() {
      const blob = new Blob([this.base32.encoded], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'base32.txt'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    copyBase58() {
      navigator.clipboard.writeText(this.base58.encoded).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadBase58() {
      const blob = new Blob([this.base58.encoded], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'base58.txt'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    loadExample32() {
      this.base32.text = 'Hello, World!'
      this.encodeBase32()
    },
    loadExample58() {
      this.base58.text = 'Hello, World!'
      this.encodeBase58()
    },
    clearAll() {
      this.base32 = {
        text: '',
        encoded: ''
      }
      this.base58 = {
        text: '',
        encoded: ''
      }
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .tool-card {
    .header-actions {
      float: right;
    }
  }

  .tab-content {
    padding: 20px 0;
  }

  .input-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }
}
</style>
