<template>
  <div class="csv-json-tool">
    <el-card>
      <div slot="header">
        <span>CSV/JSON 互转</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="11">
          <div class="section-header">
            <span>输入</span>
            <el-radio-group v-model="inputFormat" size="small">
              <el-radio-button label="csv">CSV</el-radio-button>
              <el-radio-button label="json">JSON</el-radio-button>
            </el-radio-group>
          </div>
          <el-input
            v-model="inputData"
            type="textarea"
            :rows="15"
            :placeholder="inputPlaceholder"
          />
        </el-col>

        <el-col :span="2" class="convert-buttons">
          <el-button type="primary" icon="el-icon-right" @click="convert" title="转换"></el-button>
        </el-col>

        <el-col :span="11">
          <div class="section-header">
            <span>输出</span>
            <el-radio-group v-model="outputFormat" size="small">
              <el-radio-button label="json">JSON</el-radio-button>
              <el-radio-button label="csv">CSV</el-radio-button>
            </el-radio-group>
          </div>
          <el-input
            v-model="outputData"
            type="textarea"
            :rows="15"
            readonly
            placeholder="转换结果..."
          />
        </el-col>
      </el-row>

      <el-divider>转换选项</el-divider>

      <el-form label-width="100px" v-if="inputFormat === 'csv'">
        <el-row :gutter="20">
          <el-col :span="6">
            <el-form-item label="分隔符">
              <el-select v-model="options.delimiter" style="width: 100%">
                <el-option label="逗号 (,)" value="," />
                <el-option label="分号 (;)" value=";" />
                <el-option label="制表符 (\\t)" value="\t" />
                <el-option label="竖线 (|)" value="|" />
              </el-select>
            </el-form-item>
          </el-col>
          <el-col :span="6">
            <el-form-item label="首行为标题">
              <el-switch v-model="options.header" />
            </el-form-item>
          </el-col>
          <el-col :span="6">
            <el-form-item label="跳过空行">
              <el-switch v-model="options.skipEmptyLines" />
            </el-form-item>
          </el-col>
          <el-col :span="6">
            <el-form-item label="自动类型转换">
              <el-switch v-model="options.autoType" />
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>

      <el-form label-width="100px" v-else>
        <el-row :gutter="20">
          <el-col :span="6">
            <el-form-item label="分隔符">
              <el-select v-model="options.delimiter" style="width: 100%">
                <el-option label="逗号 (,)" value="," />
                <el-option label="分号 (;)" value=";" />
                <el-option label="制表符 (\\t)" value="\t" />
                <el-option label="竖线 (|)" value="|" />
              </el-select>
            </el-form-item>
          </el-col>
          <el-col :span="6">
            <el-form-item label="包含标题">
              <el-switch v-model="options.header" />
            </el-form-item>
          </el-col>
          <el-col :span="6">
            <el-form-item label="引号包裹">
              <el-switch v-model="options.quote" />
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>

      <div class="action-buttons">
        <el-button type="primary" @click="convert">转换</el-button>
        <el-button @click="copyOutput">复制结果</el-button>
        <el-button @click="downloadOutput">下载文件</el-button>
        <el-button @click="loadExample">加载示例</el-button>
        <el-button @click="clear">清空</el-button>
      </div>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CsvJsonTool',
  data() {
    return {
      inputFormat: 'csv',
      outputFormat: 'json',
      inputData: '',
      outputData: '',
      options: {
        delimiter: ',',
        header: true,
        skipEmptyLines: true,
        autoType: true,
        quote: true
      }
    }
  },
  computed: {
    inputPlaceholder() {
      return this.inputFormat === 'csv' 
        ? '输入 CSV 数据...\n例如:\nname,age,city\nJohn,30,New York\nJane,25,Los Angeles'
        : '输入 JSON 数据...\n例如:\n[{"name":"John","age":30,"city":"New York"}]'
    }
  },
  methods: {
    convert() {
      if (!this.inputData) {
        this.$message.warning('请输入数据')
        return
      }

      try {
        if (this.inputFormat === 'csv' && this.outputFormat === 'json') {
          this.csvToJson()
        } else if (this.inputFormat === 'json' && this.outputFormat === 'csv') {
          this.jsonToCsv()
        } else {
          this.outputData = this.inputData
        }
        this.$message.success('转换成功')
      } catch (e) {
        this.$message.error('转换失败: ' + e.message)
      }
    },
    csvToJson() {
      const lines = this.inputData.split('\n')
      const result = []
      let headers = []

      const startIndex = this.options.header ? 1 : 0

      if (this.options.header && lines.length > 0) {
        headers = this.parseCSVLine(lines[0])
      }

      for (let i = startIndex; i < lines.length; i++) {
        const line = lines[i].trim()
        if (this.options.skipEmptyLines && !line) continue

        const values = this.parseCSVLine(line)
        const obj = {}

        if (this.options.header) {
          headers.forEach((header, index) => {
            let value = values[index] || ''
            if (this.options.autoType) {
              value = this.convertType(value)
            }
            obj[header] = value
          })
        } else {
          values.forEach((value, index) => {
            let val = value
            if (this.options.autoType) {
              val = this.convertType(val)
            }
            obj[`col${index}`] = val
          })
        }

        result.push(obj)
      }

      this.outputData = JSON.stringify(result, null, 2)
    },
    parseCSVLine(line) {
      const result = []
      let current = ''
      let inQuotes = false

      for (let i = 0; i < line.length; i++) {
        const char = line[i]
        const nextChar = line[i + 1]

        if (inQuotes) {
          if (char === '"') {
            if (nextChar === '"') {
              current += '"'
              i++
            } else {
              inQuotes = false
            }
          } else {
            current += char
          }
        } else {
          if (char === '"') {
            inQuotes = true
          } else if (char === this.options.delimiter) {
            result.push(current.trim())
            current = ''
          } else {
            current += char
          }
        }
      }

      result.push(current.trim())
      return result
    },
    convertType(value) {
      if (value === '') return null
      if (value === 'true') return true
      if (value === 'false') return false
      if (!isNaN(value) && value !== '') {
        return value.includes('.') ? parseFloat(value) : parseInt(value)
      }
      return value
    },
    jsonToCsv() {
      const json = JSON.parse(this.inputData)
      const array = Array.isArray(json) ? json : [json]

      if (array.length === 0) {
        this.outputData = ''
        return
      }

      const headers = Object.keys(array[0])
      let csv = ''

      if (this.options.header) {
        csv += headers.map(h => this.quoteValue(h)).join(this.options.delimiter) + '\n'
      }

      for (const item of array) {
        const values = headers.map(h => {
          let value = item[h]
          if (value === null || value === undefined) {
            value = ''
          } else if (typeof value === 'object') {
            value = JSON.stringify(value)
          }
          return this.quoteValue(String(value))
        })
        csv += values.join(this.options.delimiter) + '\n'
      }

      this.outputData = csv.trim()
    },
    quoteValue(value) {
      if (!this.options.quote) return value
      if (value.includes(this.options.delimiter) || value.includes('"') || value.includes('\n')) {
        return '"' + value.replace(/"/g, '""') + '"'
      }
      return value
    },
    copyOutput() {
      if (!this.outputData) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.outputData).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    downloadOutput() {
      if (!this.outputData) {
        this.$message.warning('没有可下载的内容')
        return
      }
      const filename = this.outputFormat === 'json' ? 'data.json' : 'data.csv'
      const blob = new Blob([this.outputData], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = filename
      link.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    loadExample() {
      if (this.inputFormat === 'csv') {
        this.inputData = `name,age,city,email
John,30,New York,john@example.com
Jane,25,Los Angeles,jane@example.com
Bob,35,Chicago,bob@example.com`
      } else {
        this.inputData = `[
  {"name": "John", "age": 30, "city": "New York", "email": "john@example.com"},
  {"name": "Jane", "age": 25, "city": "Los Angeles", "email": "jane@example.com"},
  {"name": "Bob", "age": 35, "city": "Chicago", "email": "bob@example.com"}
]`
      }
    },
    clear() {
      this.inputData = ''
      this.outputData = ''
    }
  }
}
</script>

<style scoped>
.csv-json-tool {
  padding: 20px;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.convert-buttons {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 10px;
}

.action-buttons {
  text-align: center;
  margin-top: 20px;
}
</style>
