<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>YAML 格式化</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="loadExample">加载示例</el-button>
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span>输入</span>
            </div>
            <el-input
              v-model="input"
              type="textarea"
              :rows="20"
              placeholder="输入 YAML..."
            />
          </div>
        </el-col>
        
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span>输出</span>
              <div>
                <el-button type="text" size="mini" @click="copyOutput">复制</el-button>
                <el-button type="text" size="mini" @click="downloadOutput">下载</el-button>
              </div>
            </div>
            <el-input
              v-model="output"
              type="textarea"
              :rows="20"
              readonly
              placeholder="格式化后的 YAML 将显示在这里..."
            />
          </div>
        </el-col>
      </el-row>
      
      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-form :inline="true" size="small">
            <el-form-item label="缩进">
              <el-select v-model="indent">
                <el-option label="2 空格" :value="2" />
                <el-option label="4 空格" :value="4" />
              </el-select>
            </el-form-item>
            <el-form-item label="排序">
              <el-switch v-model="sortKeys" />
            </el-form-item>
            <el-form-item>
              <el-button type="primary" @click="format">格式化</el-button>
            </el-form-item>
          </el-form>
        </el-col>
      </el-row>
      
      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">
              <span>信息</span>
            </div>
            <el-descriptions :column="4" border size="small">
              <el-descriptions-item label="输入行数">{{ inputLines }}</el-descriptions-item>
              <el-descriptions-item label="输出行数">{{ outputLines }}</el-descriptions-item>
              <el-descriptions-item label="缩进">{{ indent }} 空格</el-descriptions-item>
              <el-descriptions-item label="排序">{{ sortKeys ? '是' : '否' }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'YamlTool',
  data() {
    return {
      input: '',
      output: '',
      indent: 2,
      sortKeys: false
    }
  },
  computed: {
    inputLines() {
      return this.input.split('\n').length
    },
    outputLines() {
      return this.output.split('\n').length
    }
  },
  methods: {
    format() {
      if (!this.input.trim()) {
        this.$message.warning('请输入 YAML')
        return
      }
      
      try {
        const parsed = this.parseYaml(this.input)
        this.output = this.stringifyYaml(parsed, this.indent, this.sortKeys)
        this.$message.success('格式化成功')
      } catch (error) {
        this.$message.error('格式化失败: ' + error.message)
      }
    },
    parseYaml(str) {
      const result = {}
      const lines = str.split('\n')
      let stack = [{ level: -1, obj: result }]
      
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i]
        if (!line.trim() || line.trim().startsWith('#')) continue
        
        const level = line.search(/\S/)
        const content = line.trim()
        
        while (stack.length > 1 && stack[stack.length - 1].level >= level) {
          stack.pop()
        }
        
        let parent = stack[stack.length - 1].obj
        
        if (content.includes(':')) {
          const [key, ...valueParts] = content.split(':')
          const value = valueParts.join(':').trim()
          
          if (value === '' || value === '|') {
            const newObj = {}
            parent[key] = newObj
            stack.push({ level, obj: newObj })
          } else if (value.startsWith('|')) {
            const blockValue = this.parseBlockValue(lines, i + 1, level + 1)
            parent[key] = blockValue.value
            i = blockValue.endIndex
          } else {
            parent[key] = this.parseValue(value)
          }
        } else if (content.startsWith('- ')) {
          const value = content.substring(2)
          if (!Array.isArray(parent)) {
            const keys = Object.keys(parent)
            const lastKey = keys[keys.length - 1]
            parent[lastKey] = [parent[lastKey]]
            stack[stack.length - 1].obj = parent[lastKey]
            parent = parent[lastKey] // 更新parent为新的数组
          }
          parent.push(this.parseValue(value))
        }
      }
      
      return result
    },
    parseValue(value) {
      if (value === 'true') return true
      if (value === 'false') return false
      if (value === 'null') return null
      if (value === '~') return null
      if (!isNaN(value)) return Number(value)
      if (value.startsWith('"') && value.endsWith('"')) return value.slice(1, -1)
      if (value.startsWith("'") && value.endsWith("'")) return value.slice(1, -1)
      return value
    },
    parseBlockValue(lines, startIndex, baseLevel) {
      const values = []
      let i = startIndex
      
      while (i < lines.length) {
        const line = lines[i]
        const level = line.search(/\S/)
        
        if (level <= baseLevel && line.trim() !== '') {
          break
        }
        
        values.push(line.substring(baseLevel))
        i++
      }
      
      return { value: values.join('\n'), endIndex: i - 1 }
    },
    stringifyYaml(obj, indent, sortKeys) {
      let result = ''
      
      const process = (value, level = 0) => {
        const spaces = ' '.repeat(level * indent)
        
        if (value === null) {
          return 'null'
        }
        
        if (typeof value === 'boolean') {
          return value ? 'true' : 'false'
        }
        
        if (typeof value === 'number') {
          return String(value)
        }
        
        if (typeof value === 'string') {
          if (value.includes('\n')) {
            return '|\n' + value.split('\n').map(line => spaces + '  ' + line).join('\n')
          }
          return value
        }
        
        if (Array.isArray(value)) {
          return value.map(item => {
            const itemStr = process(item, level + 1)
            if (typeof item === 'object' && item !== null) {
              return spaces + '-\n' + itemStr
            }
            return spaces + '- ' + itemStr
          }).join('\n')
        }
        
        if (typeof value === 'object') {
          const keys = sortKeys ? Object.keys(value).sort() : Object.keys(value)
          return keys.map(key => {
            const itemStr = process(value[key], level + 1)
            if (typeof value[key] === 'object' && value[key] !== null) {
              return spaces + key + ':\n' + itemStr
            }
            return spaces + key + ': ' + itemStr
          }).join('\n')
        }
        
        return String(value)
      }
      
      result = process(obj)
      return result
    },
    copyOutput() {
      navigator.clipboard.writeText(this.output).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadOutput() {
      const blob = new Blob([this.output], { type: 'text/yaml;charset=utf-8;' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'formatted.yaml'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    loadExample() {
      this.input = `name: John Doe
age: 30
address:
  street: 123 Main St
  city: New York
  zip: 10001
hobbies:
  - reading
  - swimming
  - coding
skills:
  - name: JavaScript
    level: advanced
  - name: Python
    level: intermediate
active: true
metadata:
  created: 2024-01-01
  updated: 2024-01-15`
      this.format()
    },
    clearAll() {
      this.input = ''
      this.output = ''
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .tool-card {
    .header-actions {
      float: right;
    }
  }

  .input-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }
}
</style>
