<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>文本编辑器</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
          <el-button size="small" type="primary" @click="downloadText">下载</el-button>
          <el-button size="small" @click="copyText">复制</el-button>
        </el-button-group>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="24">
          <div class="editor-section">
            <div class="section-header">
              <span>编辑区</span>
              <div class="editor-info">
                <el-tag size="mini" type="info">{{ charCount }} 字符</el-tag>
                <el-tag size="mini" type="info">{{ lineCount }} 行</el-tag>
                <el-tag size="mini" type="info">{{ wordCount }} 词</el-tag>
              </div>
            </div>
            <el-input
              v-model="textContent"
              type="textarea"
              :rows="20"
              placeholder="在此输入或粘贴文本..."
              class="text-editor"
            />
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">文本处理工具</div>
            <div class="text-tools">
              <el-button-group>
                <el-button size="small" @click="toUpperCase">转大写</el-button>
                <el-button size="small" @click="toLowerCase">转小写</el-button>
                <el-button size="small" @click="toTitleCase">首字母大写</el-button>
              </el-button-group>
              <el-button-group>
                <el-button size="small" @click="removeExtraSpaces">去多余空格</el-button>
                <el-button size="small" @click="removeEmptyLines">去空行</el-button>
                <el-button size="small" @click="trimLines">行首尾去空</el-button>
              </el-button-group>
              <el-button-group>
                <el-button size="small" @click="sortLines">行排序</el-button>
                <el-button size="small" @click="reverseLines">行反转</el-button>
                <el-button size="small" @click="uniqueLines">去重行</el-button>
              </el-button-group>
              <el-button-group>
                <el-button size="small" @click="addLineNumbers">加行号</el-button>
                <el-button size="small" @click="removeLineNumbers">去行号</el-button>
              </el-button-group>
              <el-button-group>
                <el-button size="small" @click="base64Encode">Base64编码</el-button>
                <el-button size="small" @click="base64Decode">Base64解码</el-button>
              </el-button-group>
              <el-button-group>
                <el-button size="small" @click="urlEncode">URL编码</el-button>
                <el-button size="small" @click="urlDecode">URL解码</el-button>
              </el-button-group>
            </div>
          </el-card>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">查找替换</div>
            <el-row :gutter="10">
              <el-col :span="8">
                <el-input v-model="findText" placeholder="查找内容" size="small">
                  <template slot="prepend">查找</template>
                </el-input>
              </el-col>
              <el-col :span="8">
                <el-input v-model="replaceText" placeholder="替换为" size="small">
                  <template slot="prepend">替换</template>
                </el-input>
              </el-col>
              <el-col :span="8">
                <el-button-group>
                  <el-button size="small" type="primary" @click="replaceAll">全部替换</el-button>
                  <el-button size="small" @click="findNext">查找下一个</el-button>
                </el-button-group>
              </el-col>
            </el-row>
            <el-row style="margin-top: 10px">
              <el-col :span="24">
                <el-checkbox v-model="caseSensitive">区分大小写</el-checkbox>
                <el-checkbox v-model="useRegex">使用正则表达式</el-checkbox>
              </el-col>
            </el-row>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'TextEditorTool',
  data() {
    return {
      textContent: '',
      findText: '',
      replaceText: '',
      caseSensitive: false,
      useRegex: false,
      lastFindIndex: -1
    }
  },
  computed: {
    charCount() {
      return this.textContent.length
    },
    lineCount() {
      return this.textContent ? this.textContent.split('\n').length : 0
    },
    wordCount() {
      return this.textContent ? this.textContent.trim().split(/\s+/).filter(w => w).length : 0
    }
  },
  methods: {
    // 大小写转换
    toUpperCase() {
      this.textContent = this.textContent.toUpperCase()
      this.$message.success('已转换为大写')
    },
    toLowerCase() {
      this.textContent = this.textContent.toLowerCase()
      this.$message.success('已转换为小写')
    },
    toTitleCase() {
      this.textContent = this.textContent.replace(/\w\S*/g, txt => 
        txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase()
      )
      this.$message.success('已转换为标题格式')
    },

    // 空格和空行处理
    removeExtraSpaces() {
      this.textContent = this.textContent.replace(/\s+/g, ' ')
      this.$message.success('已去除多余空格')
    },
    removeEmptyLines() {
      this.textContent = this.textContent.split('\n').filter(line => line.trim()).join('\n')
      this.$message.success('已去除空行')
    },
    trimLines() {
      this.textContent = this.textContent.split('\n').map(line => line.trim()).join('\n')
      this.$message.success('已去除行首尾空格')
    },

    // 行操作
    sortLines() {
      this.textContent = this.textContent.split('\n').sort().join('\n')
      this.$message.success('已排序')
    },
    reverseLines() {
      this.textContent = this.textContent.split('\n').reverse().join('\n')
      this.$message.success('已反转')
    },
    uniqueLines() {
      const lines = this.textContent.split('\n')
      this.textContent = [...new Set(lines)].join('\n')
      this.$message.success('已去重')
    },

    // 行号
    addLineNumbers() {
      const lines = this.textContent.split('\n')
      const maxDigits = String(lines.length).length
      this.textContent = lines.map((line, index) => {
        const num = String(index + 1).padStart(maxDigits, '0')
        return `${num}. ${line}`
      }).join('\n')
      this.$message.success('已添加行号')
    },
    removeLineNumbers() {
      this.textContent = this.textContent.split('\n').map(line => 
        line.replace(/^\s*\d+[\.\)]\s*/, '')
      ).join('\n')
      this.$message.success('已移除行号')
    },

    // 编码解码
    base64Encode() {
      try {
        this.textContent = btoa(unescape(encodeURIComponent(this.textContent)))
        this.$message.success('Base64 编码成功')
      } catch (e) {
        this.$message.error('编码失败: ' + e.message)
      }
    },
    base64Decode() {
      try {
        this.textContent = decodeURIComponent(escape(atob(this.textContent)))
        this.$message.success('Base64 解码成功')
      } catch (e) {
        this.$message.error('解码失败: 无效的 Base64')
      }
    },
    urlEncode() {
      try {
        this.textContent = encodeURIComponent(this.textContent)
        this.$message.success('URL 编码成功')
      } catch (e) {
        this.$message.error('编码失败: ' + e.message)
      }
    },
    urlDecode() {
      try {
        this.textContent = decodeURIComponent(this.textContent)
        this.$message.success('URL 解码成功')
      } catch (e) {
        this.$message.error('解码失败: 无效的 URL 编码')
      }
    },

    // 查找替换
    replaceAll() {
      if (!this.findText) {
        this.$message.warning('请输入查找内容')
        return
      }
      try {
        let regex
        const flags = 'g' + (this.caseSensitive ? '' : 'i')
        if (this.useRegex) {
          regex = new RegExp(this.findText, flags)
        } else {
          regex = new RegExp(this.escapeRegex(this.findText), flags)
        }
        const count = (this.textContent.match(regex) || []).length
        this.textContent = this.textContent.replace(regex, this.replaceText)
        this.$message.success(`已替换 ${count} 处`)
      } catch (e) {
        this.$message.error('替换失败: ' + e.message)
      }
    },
    findNext() {
      if (!this.findText) {
        this.$message.warning('请输入查找内容')
        return
      }
      try {
        let regex
        const flags = this.caseSensitive ? '' : 'i'
        if (this.useRegex) {
          regex = new RegExp(this.findText, flags)
        } else {
          regex = new RegExp(this.escapeRegex(this.findText), flags)
        }
        
        const textarea = this.$el.querySelector('.text-editor textarea')
        const content = this.textContent
        
        // 从当前位置开始查找
        const startPos = this.lastFindIndex >= 0 ? this.lastFindIndex + 1 : 0
        const match = content.slice(startPos).match(regex)
        
        if (match) {
          const matchIndex = content.indexOf(match[0], startPos)
          this.lastFindIndex = matchIndex
          
          // 选中匹配的文本
          textarea.setSelectionRange(matchIndex, matchIndex + match[0].length)
          textarea.focus()
          
          this.$message.success(`找到: "${match[0]}"`)
        } else {
          // 从头开始查找
          const firstMatch = content.match(regex)
          if (firstMatch) {
            this.lastFindIndex = content.indexOf(firstMatch[0])
            textarea.setSelectionRange(this.lastFindIndex, this.lastFindIndex + firstMatch[0].length)
            textarea.focus()
            this.$message.success(`找到: "${firstMatch[0]}" (从头开始)`)
          } else {
            this.$message.warning('未找到匹配内容')
            this.lastFindIndex = -1
          }
        }
      } catch (e) {
        this.$message.error('查找失败: ' + e.message)
      }
    },
    escapeRegex(string) {
      return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    },

    // 文件操作
    downloadText() {
      if (!this.textContent) {
        this.$message.warning('没有可下载的内容')
        return
      }
      const blob = new Blob([this.textContent], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `text_${Date.now()}.txt`
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
      this.$message.success('已下载文本文件')
    },
    copyText() {
      if (!this.textContent) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.textContent).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    clearAll() {
      this.textContent = ''
      this.findText = ''
      this.replaceText = ''
      this.lastFindIndex = -1
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .header-actions {
    float: right;
  }

  .editor-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;

      .editor-info {
        display: flex;
        gap: 10px;
      }
    }
  }

  .text-editor {
    font-family: 'Monaco', 'Menlo', 'Consolas', monospace;
  }

  .text-tools {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;

    .el-button-group {
      margin-right: 10px;
    }
  }
}
</style>
