<template>
  <div class="json-diff-tool">
    <el-card>
      <div slot="header">
        <span>JSON 对比工具</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="11">
          <div class="section-header">
            <span>JSON A</span>
            <el-button type="text" @click="formatJsonA">格式化</el-button>
          </div>
          <el-input
            v-model="jsonA"
            type="textarea"
            :rows="15"
            placeholder="输入第一个 JSON..."
          />
        </el-col>

        <el-col :span="2" class="compare-buttons">
          <el-button type="primary" @click="compare">对比</el-button>
          <el-button @click="swap">交换</el-button>
          <el-button @click="clear">清空</el-button>
        </el-col>

        <el-col :span="11">
          <div class="section-header">
            <span>JSON B</span>
            <el-button type="text" @click="formatJsonB">格式化</el-button>
          </div>
          <el-input
            v-model="jsonB"
            type="textarea"
            :rows="15"
            placeholder="输入第二个 JSON..."
          />
        </el-col>
      </el-row>

      <el-divider>对比结果</el-divider>

      <el-tabs v-model="resultTab">
        <el-tab-pane label="差异列表" name="list">
          <el-table :data="differences" border size="small" v-if="differences.length > 0">
            <el-table-column prop="path" label="路径" width="300" />
            <el-table-column prop="type" label="类型" width="100">
              <template slot-scope="scope">
                <el-tag :type="getDiffTypeTag(scope.row.type)">{{ scope.row.type }}</el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="oldValue" label="旧值">
              <template slot-scope="scope">
                <div class="value-cell old">{{ formatValue(scope.row.oldValue) }}</div>
              </template>
            </el-table-column>
            <el-table-column prop="newValue" label="新值">
              <template slot-scope="scope">
                <div class="value-cell new">{{ formatValue(scope.row.newValue) }}</div>
              </template>
            </el-table-column>
          </el-table>
          <el-empty v-else description="没有发现差异" />
        </el-tab-pane>

        <el-tab-pane label="并排对比" name="side">
          <el-row :gutter="10">
            <el-col :span="12">
              <div class="side-panel">
                <div class="panel-header">JSON A</div>
                <pre class="json-content" v-html="highlightedA"></pre>
              </div>
            </el-col>
            <el-col :span="12">
              <div class="side-panel">
                <div class="panel-header">JSON B</div>
                <pre class="json-content" v-html="highlightedB"></pre>
              </div>
            </el-col>
          </el-row>
        </el-tab-pane>

        <el-tab-pane label="统计" name="stats">
          <el-row :gutter="20">
            <el-col :span="6">
              <el-statistic title="总差异" :value="stats.total" />
            </el-col>
            <el-col :span="6">
              <el-statistic title="新增" :value="stats.added">
                <template slot="suffix">
                  <span style="color: #67c23a">项</span>
                </template>
              </el-statistic>
            </el-col>
            <el-col :span="6">
              <el-statistic title="删除" :value="stats.removed">
                <template slot="suffix">
                  <span style="color: #f56c6c">项</span>
                </template>
              </el-statistic>
            </el-col>
            <el-col :span="6">
              <el-statistic title="修改" :value="stats.modified">
                <template slot="suffix">
                  <span style="color: #e6a23c">项</span>
                </template>
              </el-statistic>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>

      <el-divider>示例</el-divider>
      <el-button @click="loadExample">加载示例</el-button>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'JsonDiffTool',
  data() {
    return {
      jsonA: '',
      jsonB: '',
      differences: [],
      resultTab: 'list',
      highlightedA: '',
      highlightedB: ''
    }
  },
  computed: {
    stats() {
      return {
        total: this.differences.length,
        added: this.differences.filter(d => d.type === '新增').length,
        removed: this.differences.filter(d => d.type === '删除').length,
        modified: this.differences.filter(d => d.type === '修改').length
      }
    }
  },
  methods: {
    compare() {
      if (!this.jsonA || !this.jsonB) {
        this.$message.warning('请输入两个 JSON 进行对比')
        return
      }

      try {
        const objA = JSON.parse(this.jsonA)
        const objB = JSON.parse(this.jsonB)
        
        this.differences = []
        this.findDifferences(objA, objB, '')
        
        this.highlightedA = this.highlightJson(this.jsonA, 'old')
        this.highlightedB = this.highlightJson(this.jsonB, 'new')
        
        this.$message.success(`对比完成，发现 ${this.differences.length} 处差异`)
      } catch (e) {
        this.$message.error('JSON 解析错误: ' + e.message)
      }
    },
    findDifferences(objA, objB, path) {
      if (typeof objA !== typeof objB) {
        this.differences.push({
          path: path || '根',
          type: '修改',
          oldValue: objA,
          newValue: objB
        })
        return
      }

      if (objA === null || objB === null) {
        if (objA !== objB) {
          this.differences.push({
            path: path || '根',
            type: '修改',
            oldValue: objA,
            newValue: objB
          })
        }
        return
      }

      if (Array.isArray(objA) && Array.isArray(objB)) {
        const maxLen = Math.max(objA.length, objB.length)
        for (let i = 0; i < maxLen; i++) {
          const newPath = `${path}[${i}]`
          if (i >= objA.length) {
            this.differences.push({
              path: newPath,
              type: '新增',
              oldValue: undefined,
              newValue: objB[i]
            })
          } else if (i >= objB.length) {
            this.differences.push({
              path: newPath,
              type: '删除',
              oldValue: objA[i],
              newValue: undefined
            })
          } else {
            this.findDifferences(objA[i], objB[i], newPath)
          }
        }
        return
      }

      if (typeof objA === 'object' && typeof objB === 'object') {
        const keysA = Object.keys(objA)
        const keysB = Object.keys(objB)
        const allKeys = new Set([...keysA, ...keysB])

        for (const key of allKeys) {
          const newPath = path ? `${path}.${key}` : key
          if (!keysA.includes(key)) {
            this.differences.push({
              path: newPath,
              type: '新增',
              oldValue: undefined,
              newValue: objB[key]
            })
          } else if (!keysB.includes(key)) {
            this.differences.push({
              path: newPath,
              type: '删除',
              oldValue: objA[key],
              newValue: undefined
            })
          } else {
            this.findDifferences(objA[key], objB[key], newPath)
          }
        }
        return
      }

      if (objA !== objB) {
        this.differences.push({
          path: path || '根',
          type: '修改',
          oldValue: objA,
          newValue: objB
        })
      }
    },
    formatValue(value) {
      if (value === undefined) return '(不存在)'
      if (value === null) return 'null'
      if (typeof value === 'object') return JSON.stringify(value)
      return String(value)
    },
    getDiffTypeTag(type) {
      const map = {
        '新增': 'success',
        '删除': 'danger',
        '修改': 'warning'
      }
      return map[type] || 'info'
    },
    highlightJson(jsonStr, type) {
      try {
        const json = JSON.parse(jsonStr)
        let formatted = JSON.stringify(json, null, 2)
        
        for (const diff of this.differences) {
          const value = type === 'old' ? diff.oldValue : diff.newValue
          const valueStr = this.formatValue(value)
          if (formatted.includes(valueStr)) {
            const color = diff.type === '新增' ? '#f0f9eb' : 
                         diff.type === '删除' ? '#fef0f0' : '#fdf6ec'
            formatted = formatted.replace(
              new RegExp(this.escapeRegex(valueStr), 'g'),
              `<span style="background: ${color}; padding: 2px 4px; border-radius: 3px;">${valueStr}</span>`
            )
          }
        }
        
        formatted = formatted
          .replace(/"([^"]+)":/g, '<span style="color: #c678dd;">"$1"</span>:')
          .replace(/: "([^"]+)"/g, ': <span style="color: #98c379;">"$1"</span>')
          .replace(/: (\d+)/g, ': <span style="color: #d19a66;">$1</span>')
          .replace(/: (true|false)/g, ': <span style="color: #56b6c2;">$1</span>')
          .replace(/: (null)/g, ': <span style="color: #e06c75;">$1</span>')
        
        return formatted
      } catch (e) {
        return jsonStr
      }
    },
    escapeRegex(str) {
      return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    },
    formatJsonA() {
      try {
        this.jsonA = JSON.stringify(JSON.parse(this.jsonA), null, 2)
      } catch (e) {
        this.$message.error('JSON 格式错误')
      }
    },
    formatJsonB() {
      try {
        this.jsonB = JSON.stringify(JSON.parse(this.jsonB), null, 2)
      } catch (e) {
        this.$message.error('JSON 格式错误')
      }
    },
    swap() {
      const temp = this.jsonA
      this.jsonA = this.jsonB
      this.jsonB = temp
    },
    clear() {
      this.jsonA = ''
      this.jsonB = ''
      this.differences = []
      this.highlightedA = ''
      this.highlightedB = ''
    },
    loadExample() {
      this.jsonA = JSON.stringify({
        name: 'John',
        age: 30,
        email: 'john@example.com',
        address: {
          city: 'New York',
          country: 'USA'
        },
        hobbies: ['reading', 'swimming']
      }, null, 2)
      
      this.jsonB = JSON.stringify({
        name: 'John',
        age: 31,
        email: 'john.doe@example.com',
        address: {
          city: 'Los Angeles',
          country: 'USA',
          zip: '90001'
        },
        hobbies: ['reading', 'gaming', 'coding']
      }, null, 2)
    }
  }
}
</script>

<style scoped>
.json-diff-tool {
  padding: 20px;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.compare-buttons {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 10px;
}

.value-cell {
  max-height: 100px;
  overflow: auto;
  font-family: monospace;
  font-size: 12px;
}

.value-cell.old {
  background: #fef0f0;
  padding: 5px;
  border-radius: 3px;
}

.value-cell.new {
  background: #f0f9eb;
  padding: 5px;
  border-radius: 3px;
}

.side-panel {
  border: 1px solid #ebeef5;
  border-radius: 8px;
  overflow: hidden;
}

.panel-header {
  background: #f5f7fa;
  padding: 10px 15px;
  font-weight: bold;
  border-bottom: 1px solid #ebeef5;
}

.json-content {
  padding: 15px;
  margin: 0;
  font-family: 'Monaco', 'Menlo', monospace;
  font-size: 13px;
  line-height: 1.6;
  max-height: 400px;
  overflow: auto;
  white-space: pre-wrap;
  word-break: break-all;
}
</style>
